// Cloudflare Worker for FinPress
const HTML = "<!DOCTYPE html>\n<html lang=\"en\" class=\"h-full antialiased\" data-theme=\"light\">\n<head>\n  <meta charset=\"utf-8\"/>\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=5, viewport-fit=cover\"/>\n  <title>FinPress Institutional Workspace \u2014 Trader Terminal</title>\n  <script src=\"https://www.gstatic.com/antigravity/web/dev/tailwindcss.min.js\"></script>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=JetBrains+Mono:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          fontFamily: {\n            sans: ['\"Inter\"', 'system-ui', '-apple-system', 'BlinkMacSystemFont', 'sans-serif'],\n            mono: ['\"JetBrains Mono\"', 'monospace'],\n          },\n          colors: {\n            brand: { 50: '#EEF2FF', 100: '#E0E7FF', 500: '#6366F1', 600: '#4F46E5', 700: '#4338CA' }\n          }\n        }\n      }\n    }\n  </script>\n  <style>\n    html, body {\n      touch-action: manipulation;\n      -webkit-text-size-adjust: 100%;\n    }\n    body { font-family: 'Inter', -apple-system, BlinkMacSystemFont, system-ui, sans-serif; font-size: 13.5px; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; text-rendering: optimizeLegibility; }\n    .font-mono { font-family: 'JetBrains Mono', monospace; }\n    ::-webkit-scrollbar { width: 5px; height: 5px; }\n    ::-webkit-scrollbar-track { background: transparent; }\n    ::-webkit-scrollbar-thumb { background: #CBD5E1; border-radius: 4px; }\n    .dark ::-webkit-scrollbar-thumb { background: #334155; }\n    .table-row-hover:hover { background-color: rgba(99, 102, 241, 0.05); }\n    .dark .table-row-hover:hover { background-color: rgba(99, 102, 241, 0.10); }\n    mark { background-color: #FEF08A; color: #854D0E; padding: 0 2px; border-radius: 2px; font-weight: 700; }\n    .dark mark { background-color: #854D0E; color: #FEF08A; }\n    @supports (padding: max(0px)) {\n      body {\n        padding-left: env(safe-area-inset-left);\n        padding-right: env(safe-area-inset-right);\n        padding-bottom: env(safe-area-inset-bottom);\n      }\n    }\n  </style>\n</head>\n<body class=\"min-h-full bg-[#F1F5F9] text-slate-900 dark:bg-[#070B14] dark:text-slate-100 transition-colors duration-150\">\n  <div class=\"min-h-screen flex flex-col\">\n\n    <!-- ================= 1. TOPMOST MARKET PULSE & CALENDAR RIBBON ================= -->\n    <div class=\"sticky top-0 z-50 bg-[#060911] text-slate-300 text-[10.5px] font-mono px-3 py-1 flex items-center justify-between overflow-x-auto whitespace-nowrap gap-3 border-b border-slate-800/90 shadow-xs\">\n      <div class=\"flex items-center gap-3\">\n        <span class=\"text-amber-400 font-extrabold flex items-center gap-1\">\n          <span class=\"w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse\"></span>\n          <span>MARKET PULSE:</span>\n        </span>\n        <span>NIFTY <b class=\"text-emerald-400 font-bold\">24,835 (+0.64%)</b></span>\n        <span>BANK NIFTY <b class=\"text-emerald-400 font-bold\">54,120 (+0.82%)</b></span>\n        <span>INDIA VIX <b class=\"text-rose-400 font-bold\">12.85 (-3.2%)</b></span>\n        <span>BRENT <b class=\"text-amber-300 font-bold\">$74.2/bbl</b></span>\n        <span>USD/INR <b class=\"text-slate-200 font-bold\">\u20b983.65</b></span>\n      </div>\n\n      <!-- Historical Calendar & Edition Navigation -->\n      <div class=\"flex items-center gap-2 shrink-0\">\n        <div class=\"flex items-center gap-0.5 bg-slate-900 p-0.5 rounded border border-slate-700/80\">\n          <button onclick=\"navigateDate(1)\" class=\"px-1.5 py-0.2 rounded hover:bg-slate-800 text-slate-300 hover:text-white text-[10.5px] font-bold transition-colors\" title=\"Previous Date in History (Arrow Left)\">\n            \u25c0 Prev\n          </button>\n          \n          <div class=\"flex items-center gap-1 px-1 py-0.2 bg-black/50 rounded border border-slate-700/60\">\n            <span class=\"text-slate-400 text-[10px]\">\ud83d\udcc5</span>\n            <input type=\"date\" id=\"calendar-picker\" onchange=\"onCalendarSelect(this.value)\" class=\"bg-transparent text-slate-100 font-bold font-mono text-[10.5px] focus:outline-none cursor-pointer [color-scheme:dark] max-w-[102px]\"/>\n            <select id=\"edition-date-select\" onchange=\"onDateChange(this.value)\" class=\"bg-transparent text-slate-200 font-bold font-mono text-[10.5px] focus:outline-none cursor-pointer pl-1 border-l border-slate-700 max-w-[100px]\">\n              <option value=\"latest\">Latest Edition</option>\n            </select>\n          </div>\n\n          <button onclick=\"navigateDate(-1)\" class=\"px-1.5 py-0.2 rounded hover:bg-slate-800 text-slate-300 hover:text-white text-[10.5px] font-bold transition-colors\" title=\"Next Date (Arrow Right)\">\n            Next \u25b6\n          </button>\n        </div>\n\n        <div id=\"source-health-container\" class=\"flex items-center gap-1.5 font-mono text-[10px]\">\n          <!-- Dynamically populated FE / BS status pills -->\n        </div>\n\n        <span id=\"total-news-counter-badge\" class=\"px-2 py-0.5 rounded bg-emerald-500/10 border border-emerald-500/30 text-emerald-400 font-bold font-mono text-[10.5px]\">\n          \ud83d\udd25 Total: <b id=\"top-total-count\">0</b>\n        </span>\n      </div>\n    </div>\n\n    <!-- ================= 2. MAIN NAVIGATION TOOLBAR (HIGH-CONTRAST VIBRANT FINPRESS RIBBON) ================= -->\n    <header class=\"sticky top-[29px] z-40 bg-[#0C152B] border-b-2 border-indigo-600/70 text-white shadow-sm px-3 py-1 flex items-center justify-between gap-2 overflow-x-auto flex-nowrap whitespace-nowrap\">\n      \n      <!-- Left: Logo & Primary Navigation Tabs -->\n      <div class=\"flex items-center gap-2.5 shrink-0\">\n        <div class=\"flex items-center gap-1.5 shrink-0 cursor-pointer\" onclick=\"switchView('feed')\">\n          <div class=\"w-6 h-6 rounded-md bg-gradient-to-tr from-indigo-500 via-blue-600 to-indigo-700 flex items-center justify-center shadow-xs border border-indigo-400/40\">\n            <span class=\"text-white text-[10px] font-black tracking-tighter\">FP</span>\n          </div>\n          <span class=\"text-[15px] font-black tracking-tight text-white mr-0.5\">\n            Fin<span class=\"text-amber-400\">Press</span>\n          </span>\n        </div>\n\n        <!-- Navigation Tabs -->\n        <nav class=\"flex items-center bg-[#131F3B] p-0.5 rounded-md border border-indigo-900/80 text-[11px] font-medium shrink-0\">\n          <button id=\"tab-btn-feed\" onclick=\"switchView('feed')\" class=\"px-2 py-0.5 font-bold rounded transition-all bg-indigo-600 text-white shadow-xs flex items-center gap-1\">\n            <span>\u26a1 All News</span>\n            <span id=\"tab-feed-count\" class=\"px-1 rounded text-[9.5px] font-mono bg-black/30 font-bold\">0</span>\n          </button>\n          \n          <button id=\"tab-btn-anchor\" onclick=\"switchView('anchor')\" class=\"px-2 py-0.5 font-semibold rounded transition-all text-slate-300 hover:text-white flex items-center gap-1\">\n            <span>\ud83d\udcf0 Front Page</span>\n            <span id=\"tab-anchor-count\" class=\"px-1 rounded text-[9.5px] font-mono bg-amber-500/20 text-amber-300 font-bold\">0</span>\n          </button>\n\n          <button id=\"tab-btn-ipo\" onclick=\"switchView('ipo')\" class=\"px-2 py-0.5 font-semibold rounded transition-all text-slate-300 hover:text-white flex items-center gap-1\">\n            <span>\ud83d\ude80 IPO Central</span>\n            <span id=\"tab-ipo-count\" class=\"px-1 rounded text-[9.5px] font-mono bg-indigo-500/20 text-indigo-300 font-bold\">0</span>\n          </button>\n\n          <button id=\"tab-btn-corporate\" onclick=\"switchView('corporate')\" class=\"px-2 py-0.5 font-semibold rounded transition-all text-slate-300 hover:text-white flex items-center gap-1\">\n            <span>\ud83c\udfe2 Corporate</span>\n            <span id=\"tab-corp-count\" class=\"px-1 rounded text-[9.5px] font-mono bg-slate-700 text-slate-200\">0</span>\n          </button>\n\n          <button id=\"tab-btn-events\" onclick=\"switchView('events')\" class=\"px-2 py-0.5 font-semibold rounded transition-all text-slate-300 hover:text-white flex items-center gap-1\">\n            <span>\ud83d\udce2 Events</span>\n            <span id=\"tab-events-count\" class=\"px-1 rounded text-[9.5px] font-mono bg-slate-700 text-slate-200\">0</span>\n          </button>\n\n          <button id=\"tab-btn-appointments\" onclick=\"switchView('appointments')\" class=\"px-2 py-0.5 font-semibold rounded transition-all text-slate-300 hover:text-white flex items-center gap-1\">\n            <span>\ud83d\udc54 Appointments</span>\n            <span id=\"tab-appointments-count\" class=\"px-1 rounded text-[9.5px] font-mono bg-slate-700 text-slate-200\">0</span>\n          </button>\n\n          <button id=\"tab-btn-opinions\" onclick=\"switchView('opinions')\" class=\"px-2 py-0.5 font-semibold rounded transition-all text-slate-300 hover:text-white flex items-center gap-1\">\n            <span>\u270d\ufe0f Opinions</span>\n            <span id=\"tab-opinions-count\" class=\"px-1 rounded text-[9.5px] font-mono bg-slate-700 text-slate-200\">0</span>\n          </button>\n        </nav>\n      </div>\n\n      <!-- Center Controls (Compact Category Dropdown + Sentiment Filters) -->\n      <div class=\"flex items-center gap-2 shrink-0\">\n        \n        <!-- Feed Controls -->\n        <div id=\"feed-controls\" class=\"flex items-center gap-1.5\">\n          <!-- Clean Category Selector (No IPO, Corporate Events, Appointments, or Opinions) -->\n          <select id=\"category-select\" onchange=\"onCategorySelect(this.value)\" class=\"text-[11px] font-bold px-2 py-0.5 rounded border border-slate-700 bg-[#131F3B] text-slate-200 focus:outline-none focus:ring-1 focus:ring-indigo-500\">\n            <option value=\"ALL\">\u2728 All Core Sections</option>\n            <option value=\"Sector\">Sector</option>\n            <option value=\"Economy\">Economy</option>\n            <option value=\"Policy\">Policy</option>\n            <option value=\"Market\">Market (Indices & Benchmarks)</option>\n            <option value=\"Trade\">Trade & FX</option>\n            <option value=\"International News\">International</option>\n            <option value=\"Others\">General Features</option>\n          </select>\n\n          <div class=\"flex items-center bg-[#131F3B] p-0.5 rounded border border-slate-700 text-[10.5px] font-bold\">\n            <button id=\"sent-all\" onclick=\"setFeedSentiment('ALL')\" class=\"px-2 py-0.5 rounded bg-slate-800 text-white shadow-xs\">\n              All (<span id=\"feed-count-all\">0</span>)\n            </button>\n            <button id=\"sent-bullish\" onclick=\"setFeedSentiment('BULLISH')\" class=\"px-2 py-0.5 rounded text-emerald-400 hover:bg-emerald-950/40 flex items-center gap-0.5\">\n              <span>\ud83d\udfe2</span> (<span id=\"feed-count-bullish\">0</span>)\n            </button>\n            <button id=\"sent-bearish\" onclick=\"setFeedSentiment('BEARISH')\" class=\"px-2 py-0.5 rounded text-rose-400 hover:bg-rose-950/40 flex items-center gap-0.5\">\n              <span>\ud83d\udd34</span> (<span id=\"feed-count-bearish\">0</span>)\n            </button>\n          </div>\n\n          <!-- View Layout Toggle (Split vs Table Matrix) -->\n          <div class=\"flex items-center bg-[#131F3B] p-0.5 rounded border border-slate-700 text-[10.5px] font-bold\">\n            <button id=\"mode-split-btn\" onclick=\"setViewMode('split')\" class=\"px-2 py-0.5 rounded bg-indigo-600 text-white shadow-xs\" title=\"Split Screen Wire & Reading Pane\">\ud83d\udcd1 Split</button>\n            <button id=\"mode-matrix-btn\" onclick=\"setViewMode('matrix')\" class=\"px-2 py-0.5 rounded text-slate-300 hover:text-white\" title=\"Dense Institutional Financial Table\">\ud83d\udcca Table</button>\n          </div>\n        </div>\n\n        <!-- Corporate Sub-stage Filter Buttons -->\n        <div id=\"corp-controls\" class=\"hidden items-center gap-1.5\">\n          <div class=\"flex items-center bg-[#131F3B] p-0.5 rounded border border-slate-700 text-[10.5px] font-bold\">\n            <button id=\"corp-sub-all\" onclick=\"switchView('corporate')\" class=\"px-2 py-0.5 rounded bg-indigo-600 text-white shadow-xs\">All Corporate</button>\n            <button id=\"corp-sub-events\" onclick=\"switchView('events')\" class=\"px-2 py-0.5 rounded text-slate-300 hover:text-white\">\ud83d\udce2 Events</button>\n            <button id=\"corp-sub-appointments\" onclick=\"switchView('appointments')\" class=\"px-2 py-0.5 rounded text-slate-300 hover:text-white\">\ud83d\udc54 Appointments</button>\n          </div>\n        </div>\n\n        <!-- IPO Sub-stage Filter Buttons -->\n        <div id=\"ipo-controls\" class=\"hidden items-center gap-1.5\">\n          <div class=\"flex items-center bg-[#131F3B] p-0.5 rounded border border-slate-700 text-[10.5px] font-bold\">\n            <button id=\"ipo-stage-all\" onclick=\"filterIpoTable('ALL')\" class=\"px-2 py-0.5 rounded bg-indigo-600 text-white shadow-xs\">All IPOs</button>\n            <button id=\"ipo-stage-drhp\" onclick=\"filterIpoTable('DRHP')\" class=\"px-2 py-0.5 rounded text-slate-300\">\ud83d\udccb DRHP</button>\n            <button id=\"ipo-stage-bidding\" onclick=\"filterIpoTable('BIDDING')\" class=\"px-2 py-0.5 rounded text-slate-300\">\ud83d\udcc8 Bidding</button>\n            <button id=\"ipo-stage-notices\" onclick=\"filterIpoTable('NOTICES')\" class=\"px-2 py-0.5 rounded text-slate-300\">\ud83c\udfdb\ufe0f Allotments</button>\n          </div>\n        </div>\n\n      </div>\n\n      <!-- Right: Search + Theme Switcher -->\n      <div class=\"flex items-center gap-1.5 shrink-0\">\n        <div class=\"relative w-36 sm:w-44\">\n          <input type=\"text\" id=\"global-search\" oninput=\"onSearchInput()\" placeholder=\"Search stock or news...\" class=\"w-full text-[11px] pl-6 pr-5 py-0.5 rounded border border-slate-700 bg-[#131F3B] text-slate-100 placeholder-slate-400 focus:outline-none focus:border-indigo-500 font-medium\"/>\n          <span class=\"absolute left-1.5 top-1 text-slate-400 text-[10px]\">\ud83d\udd0d</span>\n          <button id=\"clear-search-btn\" onclick=\"clearSearch()\" class=\"hidden absolute right-1.5 top-0.5 text-slate-400 hover:text-white text-[10px] font-bold p-0.5\">\u2715</button>\n        </div>\n\n        <!-- Font Size Controls (A- / A+) -->\n        <div class=\"flex items-center bg-[#131F3B] p-0.5 rounded border border-slate-700 text-[10.5px] font-mono font-bold\">\n          <button onclick=\"adjustFontSize(-1)\" class=\"px-1.5 py-0.5 rounded text-slate-300 hover:text-white hover:bg-slate-800\" title=\"Decrease Font Size (A-)\">A-</button>\n          <span id=\"font-size-label\" class=\"px-1 text-[9.5px] text-slate-400 select-none\">100%</span>\n          <button onclick=\"adjustFontSize(1)\" class=\"px-1.5 py-0.5 rounded text-slate-300 hover:text-white hover:bg-slate-800\" title=\"Increase Font Size (A+)\">A+</button>\n        </div>\n\n        <button onclick=\"toggleTheme()\" class=\"w-6 h-6 rounded border border-slate-700 bg-[#131F3B] text-slate-300 hover:text-white flex items-center justify-center text-[11px] shadow-xs\" title=\"Toggle Light/Dark Theme\">\n          <span id=\"theme-icon\">\ud83c\udf19</span>\n        </button>\n      </div>\n\n    </header>\n\n    <!-- ================= MAIN THREE-COLUMN WORKSPACE (COMPRESSED DENSITY) ================= -->\n    <main class=\"mx-auto max-w-[1920px] w-full px-2.5 py-1.5 flex-1 flex flex-col gap-1.5\">\n      \n      <!-- Diagnostic Source Health Alert Banner (Appears when any paper fails) -->\n      <div id=\"source-alert-banner\" class=\"hidden px-3 py-1.5 rounded-lg bg-amber-500/15 border border-amber-500/40 text-amber-900 dark:text-amber-200 text-[11px] font-mono flex items-center justify-between gap-2 shadow-2xs\">\n        <div class=\"flex items-center gap-2\">\n          <span class=\"text-sm\">\u26a0\ufe0f</span>\n          <span id=\"source-alert-text\">Business Standard session failed to authenticate.</span>\n        </div>\n        <button onclick=\"document.getElementById('source-alert-banner').classList.add('hidden')\" class=\"text-slate-400 hover:text-white text-xs font-bold px-1.5 py-0.5\" title=\"Dismiss\">\u2715</button>\n      </div>\n\n      <!-- ================= VIEW 1: NEWS STREAM (SPLIT READER + STOCKS IN FOCUS ON RIGHT) ================= -->\n      <section id=\"view-feed\" class=\"grid grid-cols-1 lg:grid-cols-[305px_minmax(0,1fr)_260px] xl:grid-cols-[325px_minmax(0,1fr)_275px] gap-2 items-start\">\n        \n        <!-- COLUMN 1: HIGH-DENSITY TERMINAL NEWS WIRE (1-LINER STORIES, MAX 10 PER PAGE) -->\n        <div class=\"rounded-lg bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 overflow-hidden shadow-xs flex flex-col\">\n          <div class=\"px-2.5 py-1.5 border-b border-slate-200 dark:border-slate-800 bg-slate-100/90 dark:bg-slate-900/80 flex items-center justify-between text-[11px] font-mono\">\n            <span id=\"feed-list-count\" class=\"font-extrabold text-slate-900 dark:text-slate-100\">0 Stories</span>\n            <div class=\"flex items-center gap-1\">\n              <button onclick=\"navigateStory(-1)\" class=\"px-1.5 py-0.2 rounded bg-white dark:bg-slate-800 hover:bg-indigo-50 text-[10px] font-bold text-slate-900 dark:text-slate-200 border border-slate-300 dark:border-slate-700\" title=\"Previous Story (K or Up Arrow)\">\u25b2 Prev</button>\n              <button onclick=\"navigateStory(1)\" class=\"px-1.5 py-0.2 rounded bg-white dark:bg-slate-800 hover:bg-indigo-50 text-[10px] font-bold text-slate-900 dark:text-slate-200 border border-slate-300 dark:border-slate-700\" title=\"Next Story (J or Down Arrow)\">\u25bc Next</button>\n            </div>\n          </div>\n\n          <div id=\"feed-list-container\" class=\"divide-y divide-slate-100 dark:divide-slate-800/80 flex flex-col\">\n            <!-- Dynamically populated 1-liner story items (Max 10) -->\n          </div>\n\n          <!-- COLUMN 1 PAGINATION BAR (10 STORIES PER PAGE) -->\n          <div id=\"feed-pagination\" class=\"px-2.5 py-1.5 border-t border-slate-200 dark:border-slate-800 bg-slate-50/90 dark:bg-slate-900/80 flex items-center justify-between text-[11px] font-mono\">\n            <span id=\"feed-pagination-info\" class=\"font-bold text-slate-700 dark:text-slate-300\">Page 1 / 1</span>\n            <div class=\"flex items-center gap-1\">\n              <button id=\"feed-prev-page\" onclick=\"changeFeedPage(-1)\" class=\"px-2 py-0.5 rounded bg-white dark:bg-slate-800 hover:bg-indigo-50 text-[10.5px] font-bold text-slate-900 dark:text-slate-200 border border-slate-300 dark:border-slate-700 shadow-2xs\">\u25c0 Prev</button>\n              <button id=\"feed-next-page\" onclick=\"changeFeedPage(1)\" class=\"px-2 py-0.5 rounded bg-white dark:bg-slate-800 hover:bg-indigo-50 text-[10.5px] font-bold text-slate-900 dark:text-slate-200 border border-slate-300 dark:border-slate-700 shadow-2xs\">Next \u25b6</button>\n            </div>\n          </div>\n        </div>\n\n        <!-- COLUMN 2: ACTIVE STORY DEEP DIVE & CATALYST INTELLIGENCE (WIDE READING PANE) -->\n        <div id=\"feed-detail-wrapper\" class=\"rounded-lg bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 p-3 sm:p-4 shadow-xs lg:sticky lg:top-[70px] flex flex-col gap-2.5 lg:min-h-[calc(100vh-5.5rem)] lg:max-h-[calc(100vh-5.5rem)] lg:overflow-y-auto\">\n          <div id=\"feed-detail-container\">\n            <!-- Dynamically populated active story intelligence -->\n          </div>\n        </div>\n\n        <!-- COLUMN 3: RIGHT HAND SIDE PANEL (STOCKS IN FOCUS - PROMINENT & EXPANDED) -->\n        <aside class=\"flex flex-col gap-2 lg:sticky lg:top-[70px] lg:max-h-[calc(100vh-5.5rem)] lg:overflow-y-auto\">\n          \n          <!-- Stocks in Focus Card -->\n          <div class=\"rounded-lg bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 p-3 shadow-xs flex flex-col gap-2\">\n            <div class=\"flex items-center justify-between border-b border-slate-100 dark:border-slate-800 pb-2\">\n              <span class=\"text-[12px] font-bold uppercase tracking-wider text-slate-900 dark:text-slate-100 flex items-center gap-1.5 font-mono\">\n                <span>\ud83c\udff7\ufe0f</span> <span>Stocks in Focus</span>\n              </span>\n              <button id=\"clear-ticker-filter\" onclick=\"clearTickerFilter()\" class=\"hidden text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-bold hover:underline\">\n                Clear Filter (\u2715)\n              </button>\n            </div>\n\n            <p class=\"text-[11px] text-slate-500 dark:text-slate-400 leading-tight font-medium\">Click any stock to filter news:</p>\n\n            <!-- Stock Ticker Pill Matrix -->\n            <div id=\"stocks-focus-list\" class=\"flex flex-wrap gap-1.5 max-h-[220px] lg:max-h-[calc(100vh-10rem)] overflow-y-auto pt-0.5\">\n              <!-- Dynamically populated ticker chips -->\n            </div>\n          </div>\n\n        </aside>\n\n      </section>\n\n      <!-- ================= VIEW 2: TABULAR IPO CENTRAL ================= -->\n      <section id=\"view-ipo\" class=\"hidden flex-col gap-2\">\n        <div class=\"rounded-xl bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 shadow-xs overflow-hidden flex flex-col\">\n          \n          <div class=\"px-4 py-2.5 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-slate-50/70 dark:bg-[#11172A]/70 text-[12.5px] font-mono\">\n            <span class=\"font-bold text-slate-800 dark:text-slate-200 flex items-center gap-2\">\n              <span>\ud83d\ude80</span> <span>PRIMARY MARKET TRACKER (Mainboard & SME IPO Filings)</span>\n            </span>\n            <span class=\"text-slate-400\">Total Tracked: <b id=\"ipo-table-visible-count\" class=\"text-brand-600 font-bold\">0</b> Records</span>\n          </div>\n\n          <div class=\"overflow-x-auto max-h-[calc(100vh-7.5rem)] overflow-y-auto\">\n            <table class=\"w-full text-left border-collapse text-[13.5px]\">\n              <thead class=\"sticky top-0 z-10 bg-slate-100 dark:bg-[#141A2E] shadow-xs\">\n                <tr class=\"border-b border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400 text-[11.5px] font-mono uppercase tracking-wider font-bold\">\n                  <th class=\"py-2.5 px-3.5\">#</th>\n                  <th class=\"py-2.5 px-3.5 min-w-[240px]\">Company / Issuer & Exchange</th>\n                  <th class=\"py-2.5 px-3.5 min-w-[120px]\">Issue Size</th>\n                  <th class=\"py-2.5 px-3.5 min-w-[140px]\">Stage / Status</th>\n                  <th class=\"py-2.5 px-3.5 min-w-[130px]\">Subscription Demand</th>\n                  <th class=\"py-2.5 px-3.5 min-w-[360px]\">Key Analyst Insight & Breakdown</th>\n                  <th class=\"py-2.5 px-3.5 min-w-[130px]\">Source</th>\n                  <th class=\"py-2.5 px-3.5 text-center\">Full Info</th>\n                </tr>\n              </thead>\n              <tbody id=\"ipo-table-body\" class=\"divide-y divide-slate-100 dark:divide-slate-800/70\">\n                <!-- Dynamically populated IPO rows -->\n              </tbody>\n            </table>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ================= VIEW 3: TABULAR MASTER NEWS MATRIX (INSTITUTIONAL TABLE) ================= -->\n      <section id=\"view-matrix\" class=\"hidden flex-col gap-2\">\n        <div class=\"rounded-xl bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 shadow-xs overflow-hidden flex flex-col\">\n          \n          <div class=\"px-4 py-2.5 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-slate-50/70 dark:bg-[#11172A]/70 text-[12.5px] font-mono\">\n            <span class=\"font-bold text-slate-800 dark:text-slate-200 flex items-center gap-2\">\n              <span>\ud83d\udcca</span> <span>MASTER FINANCIAL NEWS MATRIX (Full Unabridged Intelligence Stream)</span>\n            </span>\n            <span class=\"text-slate-400\">Total Displayed: <b id=\"matrix-table-visible-count\" class=\"text-brand-600 font-bold\">0</b> Stories</span>\n          </div>\n\n          <div class=\"overflow-x-auto max-h-[calc(100vh-7.5rem)] overflow-y-auto\">\n            <table class=\"w-full text-left border-collapse text-[13.5px]\">\n              <thead class=\"sticky top-0 z-10 bg-slate-100 dark:bg-[#141A2E] shadow-xs\">\n                <tr class=\"border-b border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400 text-[11px] font-mono uppercase tracking-wider font-bold\">\n                  <th class=\"py-2.5 px-3\">#</th>\n                  <th class=\"py-2.5 px-3.5 min-w-[280px]\">Headline & Core Development</th>\n                  <th class=\"py-2.5 px-3 min-w-[110px]\">Section</th>\n                  <th class=\"py-2.5 px-3 min-w-[100px]\">Sentiment</th>\n                  <th class=\"py-2.5 px-3 min-w-[120px]\">Page / Source</th>\n                  <th class=\"py-2.5 px-3 min-w-[130px]\">Tickers</th>\n                  <th class=\"py-2.5 px-3.5 min-w-[360px]\">Executive Intelligence Summary</th>\n                  <th class=\"py-2.5 px-3 text-center\">Full Info</th>\n                </tr>\n              </thead>\n              <tbody id=\"matrix-table-body\" class=\"divide-y divide-slate-100 dark:divide-slate-800/70\">\n                <!-- Dynamically populated Matrix rows -->\n              </tbody>\n            </table>\n          </div>\n\n        </div>\n      </section>\n\n    </main>\n\n  </div>\n\n  <!-- ================= STORY FULL DETAILS MODAL ================= -->\n  <div id=\"story-modal\" class=\"fixed inset-0 z-50 bg-black/60 backdrop-blur-xs hidden items-center justify-center p-4\">\n    <div class=\"bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 rounded-2xl max-w-3xl w-full p-6 shadow-2xl flex flex-col gap-4 max-h-[90vh] overflow-y-auto\">\n      <div class=\"flex items-start justify-between border-b border-slate-100 dark:border-slate-800 pb-3\">\n        <div>\n          <div class=\"flex items-center gap-2\">\n            <span id=\"story-modal-category\" class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-bold bg-slate-100 text-slate-800 dark:bg-slate-800 dark:text-slate-200\">Policy</span>\n            <span id=\"story-modal-sentiment\" class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-bold bg-emerald-50 text-emerald-800 border border-emerald-200\">\ud83d\udfe2 BULLISH</span>\n            <span id=\"story-modal-pages\" class=\"text-xs font-mono text-slate-500\">FE (Page 1)</span>\n          </div>\n          <h2 id=\"story-modal-headline\" class=\"text-xl font-extrabold text-slate-900 dark:text-white mt-1 leading-tight\">Headline</h2>\n        </div>\n        <button onclick=\"closeStoryModal()\" class=\"w-8 h-8 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-500 hover:text-slate-900 dark:hover:text-white font-bold flex items-center justify-center shrink-0\">\u2715</button>\n      </div>\n\n      <div id=\"story-modal-tickers-container\" class=\"flex items-center gap-1.5 flex-wrap\">\n        <!-- Tickers -->\n      </div>\n\n      <div id=\"story-modal-kpis-container\">\n        <!-- KPI Badges -->\n      </div>\n\n      <!-- \u26a1 EXECUTIVE GIST (INDIGO CARD) -->\n      <div class=\"p-3.5 rounded-xl bg-indigo-50/80 dark:bg-[#10182E] border border-indigo-200/90 dark:border-indigo-800 shadow-2xs\">\n        <p class=\"text-[11px] font-mono uppercase tracking-wider font-extrabold text-indigo-950 dark:text-indigo-300 mb-1 flex items-center gap-1\">\n          <span>\u26a1</span> <span>Executive Gist (Core Takeaway)</span>\n        </p>\n        <div id=\"story-modal-brief\" class=\"space-y-1.5\"></div>\n      </div>\n\n      <!-- \ud83d\udccc KEY ANALYST DATA POINTS (AMBER CARD) -->\n      <div class=\"p-3 rounded-xl bg-amber-50/70 dark:bg-[#201608] border border-amber-300 dark:border-amber-800/80 shadow-2xs\">\n        <p class=\"text-[11px] font-mono uppercase tracking-wider font-extrabold text-amber-950 dark:text-amber-300 mb-1.5 flex items-center gap-1\">\n          <span>\ud83d\udccc</span> <span>Key Analyst Data Points</span>\n        </p>\n        <ul id=\"story-modal-bullets\" class=\"space-y-1.5\">\n          <!-- Bullets -->\n        </ul>\n      </div>\n\n      <!-- \ud83d\udca1 TRADER CATALYST (DYNAMIC EMERALD/ROSE/SLATE CARD) -->\n      <div id=\"story-modal-catalyst-box\" class=\"p-3 rounded-xl border border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-[#11172A] shadow-2xs\">\n        <p class=\"text-[11px] font-mono uppercase tracking-wider font-bold text-slate-600 dark:text-slate-300 mb-1 flex items-center gap-1\">\n          <span>\ud83d\udca1</span> <span>Trader Catalyst & Impact Analysis</span>\n        </p>\n        <div id=\"story-modal-catalyst\" class=\"text-xs text-slate-800 dark:text-slate-200 leading-relaxed font-medium bg-white dark:bg-[#0B1020] p-2.5 rounded-lg border border-slate-200/80 dark:border-slate-800\"></div>\n      </div>\n\n      <div class=\"flex items-center justify-between pt-2 border-t border-slate-100 dark:border-slate-800 text-xs font-mono text-slate-400\">\n        <span id=\"story-modal-source\">FinPress Intelligence</span>\n        <button onclick=\"closeStoryModal()\" class=\"px-4 py-1.5 bg-brand-600 hover:bg-brand-700 text-white font-bold rounded-lg transition-colors\">Close</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- ================= IPO FULL DETAILS MODAL ================= -->\n  <div id=\"ipo-modal\" class=\"fixed inset-0 z-50 bg-black/60 backdrop-blur-xs hidden items-center justify-center p-4\">\n    <div class=\"bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 rounded-2xl max-w-2xl w-full p-6 shadow-2xl flex flex-col gap-4\">\n      <div class=\"flex items-start justify-between border-b border-slate-100 dark:border-slate-800 pb-3\">\n        <div>\n          <div class=\"flex items-center gap-2\">\n            <span id=\"modal-ipo-exchange\" class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-bold bg-indigo-50 text-indigo-700 border border-indigo-200 dark:bg-indigo-950/60 dark:text-indigo-300\">NSE / BSE</span>\n            <span id=\"modal-ipo-stage\" class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-bold bg-amber-50 text-amber-800 border border-amber-200\">DRHP Filed</span>\n          </div>\n          <h2 id=\"modal-ipo-company\" class=\"text-xl font-extrabold text-slate-900 dark:text-white mt-1\">Company Name</h2>\n        </div>\n        <button onclick=\"closeIpoModal()\" class=\"w-8 h-8 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-500 hover:text-slate-900 dark:hover:text-white font-bold flex items-center justify-center\">\u2715</button>\n      </div>\n\n      <div class=\"grid grid-cols-2 gap-3 bg-slate-50 dark:bg-[#151B2E] p-3 rounded-xl border border-slate-200/80 dark:border-slate-800 font-mono text-xs\">\n        <div>\n          <span class=\"text-slate-400\">Issue Size:</span>\n          <p id=\"modal-ipo-size\" class=\"text-slate-900 dark:text-white font-bold text-sm\">\u20b90 Cr</p>\n        </div>\n        <div>\n          <span class=\"text-slate-400\">Demand / Subscription:</span>\n          <p id=\"modal-ipo-demand\" class=\"text-emerald-600 dark:text-emerald-400 font-bold text-sm\">Filing Stage</p>\n        </div>\n      </div>\n\n      <div>\n        <p class=\"text-[11px] font-mono uppercase tracking-wider font-bold text-slate-400 mb-1\">Headline & Filing Announcement</p>\n        <p id=\"modal-ipo-headline\" class=\"text-sm font-bold text-slate-800 dark:text-slate-200\"></p>\n      </div>\n\n      <div>\n        <p class=\"text-[11px] font-mono uppercase tracking-wider font-bold text-brand-600 dark:text-brand-400 mb-1\">Detailed Analyst Insight & Comprehensive Notes</p>\n        <p id=\"modal-ipo-details\" class=\"text-sm text-slate-700 dark:text-slate-300 leading-relaxed bg-slate-50 dark:bg-[#11172A] p-3.5 rounded-xl border border-slate-200/80 dark:border-slate-800\"></p>\n      </div>\n\n      <div class=\"flex items-center justify-between pt-2 border-t border-slate-100 dark:border-slate-800 text-xs font-mono text-slate-400\">\n        <span id=\"modal-ipo-source\">Source: FE / BS</span>\n        <button onclick=\"closeIpoModal()\" class=\"px-4 py-1.5 bg-brand-600 hover:bg-brand-700 text-white font-bold rounded-lg transition-colors\">Close</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- ================= CLIENT JAVASCRIPT ================= -->\n  <script>\n    let rawReport = null;\n    let stories = [];\n    let ipoList = [];\n    let currentView = \"feed\";\n    let selectedFeedCategory = \"ALL\";\n    let selectedFeedSentiment = \"ALL\";\n    let activeTickerFilter = null;\n    let selectedStoryIndex = 0;\n    let currentFeedPage = 1;\n    const FEED_PAGE_SIZE = 12;\n    let currentIpoFilter = \"ALL\";\n    let currentSearchQuery = \"\";\n    let availableDates = [];\n    let currentDateIndex = 0;\n\n    const allowedSections = [\n      \"ALL\", \"Sector\", \"Economy\", \"Policy\", \"Market\", \"Trade\", \"International News\", \"Others\"\n    ];\n\n    const tickerDictionary = [\n      \"RELIANCE\", \"TCS\", \"INFOSYS\", \"INFY\", \"HDFC BANK\", \"HDFCBANK\", \"ICICI BANK\", \"ICICIBANK\", \"SBI\", \"SBIN\",\n      \"BHARTI AIRTEL\", \"AIRTEL\", \"ITC\", \"KOTAK BANK\", \"L&T\", \"LT\", \"TATA MOTORS\", \"TATA STEEL\", \"MARUTI\",\n      \"SUN PHARMA\", \"TITAN\", \"BAJAJ FINANCE\", \"ADANI\", \"NTPC\", \"ONGC\", \"POWERGRID\", \"JSW STEEL\", \"COAL INDIA\",\n      \"COALINDIA\", \"SAIL\", \"BCCL\", \"NCL\", \"HINDALCO\", \"WIPRO\", \"TECH MAHINDRA\", \"ZOMATO\", \"PAYTM\", \"SWIGGY\",\n      \"HAL\", \"BEL\", \"BHEL\", \"BDL\", \"IRFC\", \"RVNL\", \"IREDA\", \"VEDANTA\", \"DLF\", \"GODREJ\", \"AXIS BANK\", \"ASIAN PAINTS\",\n      \"ULTRATECH\", \"HERO MOTOCORP\", \"BAJAJ AUTO\", \"EICHER\", \"DR REDDY\", \"CIPLA\", \"TRENT\", \"DMART\", \"POLYCAB\",\n      \"DIXON\", \"BSE\", \"MCX\", \"CDSL\", \"AUTO\", \"BANKING\", \"DEFENCE\", \"REALTY\", \"PHARMA\", \"IT\", \"METALS\", \"ENERGY\",\n      \"TELECOM\", \"FMCG\", \"INFRA\", \"POWER\"\n    ];\n\n    function initTheme() {\n      const t = localStorage.getItem('finbrief_theme') || 'light';\n      applyTheme(t);\n    }\n    function toggleTheme() {\n      const isDark = document.documentElement.classList.contains('dark');\n      const next = isDark ? 'light' : 'dark';\n      applyTheme(next);\n      localStorage.setItem('finbrief_theme', next);\n    }\n    function applyTheme(t) {\n      const icon = document.getElementById('theme-icon');\n      if (t === 'dark') {\n        document.documentElement.classList.add('dark');\n        if (icon) icon.textContent = '\u2600\ufe0f';\n      } else {\n        document.documentElement.classList.remove('dark');\n        if (icon) icon.textContent = '\ud83c\udf19';\n      }\n    }\n\n    let currentLayoutMode = \"split\";\n\n    function setViewMode(mode) {\n      currentLayoutMode = mode;\n      const splitBtn = document.getElementById(\"mode-split-btn\");\n      const matrixBtn = document.getElementById(\"mode-matrix-btn\");\n      const viewFeed = document.getElementById(\"view-feed\");\n      const viewMatrix = document.getElementById(\"view-matrix\");\n\n      if (splitBtn) splitBtn.className = mode === \"split\" ? \"px-2 py-0.5 rounded bg-indigo-600 text-white shadow-xs\" : \"px-2 py-0.5 rounded text-slate-300 hover:text-white\";\n      if (matrixBtn) matrixBtn.className = mode === \"matrix\" ? \"px-2 py-0.5 rounded bg-indigo-600 text-white shadow-xs\" : \"px-2 py-0.5 rounded text-slate-300 hover:text-white\";\n\n      if (currentView === \"ipo\") return;\n\n      if (mode === \"split\") {\n        viewFeed.classList.remove(\"hidden\");\n        viewFeed.classList.add(\"grid\");\n        viewMatrix.classList.add(\"hidden\");\n        viewMatrix.classList.remove(\"flex\");\n        renderFeedList();\n      } else {\n        viewFeed.classList.add(\"hidden\");\n        viewFeed.classList.remove(\"grid\");\n        viewMatrix.classList.remove(\"hidden\");\n        viewMatrix.classList.add(\"flex\");\n        renderMatrixTable();\n      }\n    }\n\n    function switchView(viewName) {\n      currentView = viewName;\n      const tabFeed = document.getElementById(\"tab-btn-feed\");\n      const tabAnchor = document.getElementById(\"tab-btn-anchor\");\n      const tabIpo = document.getElementById(\"tab-btn-ipo\");\n      const tabCorp = document.getElementById(\"tab-btn-corporate\");\n      const tabEvents = document.getElementById(\"tab-btn-events\");\n      const tabAppointments = document.getElementById(\"tab-btn-appointments\");\n      const tabOpinions = document.getElementById(\"tab-btn-opinions\");\n      const viewFeed = document.getElementById(\"view-feed\");\n      const viewIpo = document.getElementById(\"view-ipo\");\n      const viewMatrix = document.getElementById(\"view-matrix\");\n      const feedControls = document.getElementById(\"feed-controls\");\n      const ipoControls = document.getElementById(\"ipo-controls\");\n      const corpControls = document.getElementById(\"corp-controls\");\n\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n\n      [tabFeed, tabAnchor, tabIpo, tabCorp, tabEvents, tabAppointments, tabOpinions].forEach(b => {\n        if (b) b.className = \"px-2 py-0.5 font-semibold rounded transition-all text-slate-300 hover:text-white flex items-center gap-1\";\n      });\n\n      if (viewName === \"ipo\") {\n        tabIpo.className = \"px-2 py-0.5 font-bold rounded transition-all bg-indigo-600 text-white shadow-xs flex items-center gap-1\";\n        viewFeed.classList.add(\"hidden\");\n        viewFeed.classList.remove(\"grid\");\n        viewMatrix.classList.add(\"hidden\");\n        viewMatrix.classList.remove(\"flex\");\n        viewIpo.classList.remove(\"hidden\");\n        viewIpo.classList.add(\"flex\");\n        feedControls.classList.add(\"hidden\");\n        if (corpControls) corpControls.classList.add(\"hidden\");\n        ipoControls.classList.remove(\"hidden\");\n        ipoControls.classList.add(\"flex\");\n        renderIpoTable();\n        return;\n      }\n\n      viewIpo.classList.add(\"hidden\");\n      viewIpo.classList.remove(\"flex\");\n      ipoControls.classList.add(\"hidden\");\n\n      if (currentLayoutMode === \"split\") {\n        viewFeed.classList.remove(\"hidden\");\n        viewFeed.classList.add(\"grid\");\n        viewMatrix.classList.add(\"hidden\");\n        viewMatrix.classList.remove(\"flex\");\n      } else {\n        viewFeed.classList.add(\"hidden\");\n        viewFeed.classList.remove(\"grid\");\n        viewMatrix.classList.remove(\"hidden\");\n        viewMatrix.classList.add(\"flex\");\n      }\n\n      if (viewName === \"feed\") {\n        tabFeed.className = \"px-2 py-0.5 font-bold rounded transition-all bg-indigo-600 text-white shadow-xs flex items-center gap-1\";\n        selectedFeedCategory = \"ALL\";\n        document.getElementById(\"category-select\").value = \"ALL\";\n        feedControls.classList.remove(\"hidden\");\n        if (corpControls) corpControls.classList.add(\"hidden\");\n      } else if (viewName === \"anchor\") {\n        tabAnchor.className = \"px-2 py-0.5 font-bold rounded transition-all bg-indigo-600 text-white shadow-xs flex items-center gap-1\";\n        selectedFeedCategory = \"ANCHOR\";\n        feedControls.classList.remove(\"hidden\");\n        if (corpControls) corpControls.classList.add(\"hidden\");\n      } else if (viewName === \"corporate\") {\n        tabCorp.className = \"px-2 py-0.5 font-bold rounded transition-all bg-indigo-600 text-white shadow-xs flex items-center gap-1\";\n        selectedFeedCategory = \"CORPORATE_ALL\";\n        feedControls.classList.add(\"hidden\");\n        if (corpControls) {\n          corpControls.classList.remove(\"hidden\");\n          corpControls.classList.add(\"flex\");\n          document.getElementById(\"corp-sub-all\").className = \"px-2 py-0.5 rounded bg-indigo-600 text-white shadow-xs\";\n          document.getElementById(\"corp-sub-events\").className = \"px-2 py-0.5 rounded text-slate-300 hover:text-white\";\n          document.getElementById(\"corp-sub-appointments\").className = \"px-2 py-0.5 rounded text-slate-300 hover:text-white\";\n        }\n      } else if (viewName === \"events\") {\n        tabEvents.className = \"px-2 py-0.5 font-bold rounded transition-all bg-indigo-600 text-white shadow-xs flex items-center gap-1\";\n        selectedFeedCategory = \"EVENTS\";\n        feedControls.classList.add(\"hidden\");\n        if (corpControls) {\n          corpControls.classList.remove(\"hidden\");\n          corpControls.classList.add(\"flex\");\n          document.getElementById(\"corp-sub-all\").className = \"px-2 py-0.5 rounded text-slate-300 hover:text-white\";\n          document.getElementById(\"corp-sub-events\").className = \"px-2 py-0.5 rounded bg-indigo-600 text-white shadow-xs\";\n          document.getElementById(\"corp-sub-appointments\").className = \"px-2 py-0.5 rounded text-slate-300 hover:text-white\";\n        }\n      } else if (viewName === \"appointments\") {\n        tabAppointments.className = \"px-2 py-0.5 font-bold rounded transition-all bg-indigo-600 text-white shadow-xs flex items-center gap-1\";\n        selectedFeedCategory = \"APPOINTMENTS\";\n        feedControls.classList.add(\"hidden\");\n        if (corpControls) {\n          corpControls.classList.remove(\"hidden\");\n          corpControls.classList.add(\"flex\");\n          document.getElementById(\"corp-sub-all\").className = \"px-2 py-0.5 rounded text-slate-300 hover:text-white\";\n          document.getElementById(\"corp-sub-events\").className = \"px-2 py-0.5 rounded text-slate-300 hover:text-white\";\n          document.getElementById(\"corp-sub-appointments\").className = \"px-2 py-0.5 rounded bg-indigo-600 text-white shadow-xs\";\n        }\n      } else if (viewName === \"opinions\") {\n        tabOpinions.className = \"px-2 py-0.5 font-bold rounded transition-all bg-indigo-600 text-white shadow-xs flex items-center gap-1\";\n        selectedFeedCategory = \"OPINIONS\";\n        feedControls.classList.remove(\"hidden\");\n        if (corpControls) corpControls.classList.add(\"hidden\");\n      }\n\n      if (currentLayoutMode === \"split\") renderFeedList();\n      else renderMatrixTable();\n    }\n\n    function onCategorySelect(val) {\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n      selectedFeedCategory = val;\n      renderFeedList();\n    }\n\n    function isFillerHeadline(hl) {\n      const h = hl.toLowerCase();\n      return (\n        h.includes(\"special edition and general overview\") ||\n        h.includes(\"general overview\") ||\n        h.includes(\"newspaper overview\") ||\n        h.includes(\"sunday special edition\") ||\n        h.includes(\"fe sunday special\") ||\n        h.includes(\"edition overview\") ||\n        h.includes(\"e-paper index\") ||\n        h.includes(\"table of contents\")\n      );\n    }\n\n    function parseStory(story, idx) {\n      if (isFillerHeadline(story.headline)) return null;\n\n      const fullText = (story.headline + \" \" + story.brief_details + \" \" + (story.bullet_points || []).join(\" \")).toLowerCase();\n      const pageStr = (story.page_numbers || \"\").toLowerCase();\n\n      // Strict Market Section Rule: Bank disclosures/Statutory notices belong in Corporate Events\n      let category = story.category;\n      if (category === \"Market\" || category === \"Others\") {\n        const noticeTerms = [\"disclosure\", \"public notice\", \"statutory notice\", \"possession notice\", \"postal ballot\", \"e-voting\", \"annual general meeting\", \"agm notice\", \"egm notice\", \"co-op bank\", \"co-operative bank\", \"financial and regulatory disclosure\", \"auction notice\"];\n        if (noticeTerms.some(t => fullText.includes(t))) {\n          category = \"Corporate Events\";\n        }\n      }\n\n      // Detect Opinions / Editorial\n      const isOpinion = pageStr.includes(\"opinion\") || pageStr.includes(\"edit\") || pageStr.includes(\"column\") || pageStr.includes(\"commentary\") || fullText.includes(\"op-ed\") || fullText.includes(\"editorial view\");\n\n      // Strict Front Page Anchors: Must be Page 1 and strictly genuine NEWS (NOT IPOs, Corporate Announcements, or Disclosures)\n      const isPage1Location = pageStr.includes(\"page 1\") || pageStr.includes(\"page 01\") || pageStr.includes(\"p.1\") || pageStr.includes(\"front\") || pageStr.includes(\"lead\");\n      const isAnnouncementOrIpo = category === \"IPO\" || category === \"Corporate Events\" || category === \"Corporate Appointments\" || isOpinion || fullText.includes(\"drhp\") || fullText.includes(\"statutory notice\") || fullText.includes(\"public notice\") || fullText.includes(\"disclosure\");\n      const isFrontPage = (isPage1Location || idx < 4) && !isAnnouncementOrIpo;\n\n      const bullishTriggers = [\n        { k: \"order win\", r: \"Contract / Order Inflow expands near-term revenue visibility.\" },\n        { k: \"mou\", r: \"Strategic MoU / Partnership accelerates joint development and market reach.\" },\n        { k: \"expansion\", r: \"Capacity Expansion / New facility enhances long-term operational throughput.\" },\n        { k: \"profit up\", r: \"Strong bottom-line growth signals healthy operational leverage.\" },\n        { k: \"revenue up\", r: \"Topline growth indicates robust market demand and pricing power.\" },\n        { k: \"approval\", r: \"Key regulatory/government clearance removes project bottleneck.\" },\n        { k: \"dividend\", r: \"Shareholder payout / capital return signals healthy balance-sheet liquidity.\" },\n        { k: \"exemption\", r: \"Policy duty waiver / tax exemption improves gross margins.\" },\n        { k: \"surge\", r: \"Sharp positive volume/demand breakout across core business segments.\" }\n      ];\n\n      const bearishRisks = [\n        { k: \"penalty\", r: \"Regulatory penalty / Show-cause notice creates near-term compliance headwind.\" },\n        { k: \"fine\", r: \"Monetary penalty imposes financial liability and compliance friction.\" },\n        { k: \"probe\", r: \"Regulatory/tax scrutiny introduces headline risk and governance scrutiny.\" },\n        { k: \"loss\", r: \"Widening losses or margin compression weigh on fundamental valuation.\" },\n        { k: \"slump\", r: \"Demand deceleration or volume contraction creates earnings drag.\" },\n        { k: \"falls\", r: \"Topline or net margin contraction signals weakening operating leverage.\" },\n        { k: \"tax hike\", r: \"Increased duty/tax burdens directly compress profit spreads.\" },\n        { k: \"curb\", r: \"Export/import curbs or policy restrictions limit addressable business.\" }\n      ];\n\n      let matchedBullish = [];\n      bullishTriggers.forEach(t => { if (fullText.includes(t.k)) matchedBullish.push(t.r); });\n\n      let matchedBearish = [];\n      bearishRisks.forEach(t => { if (fullText.includes(t.k)) matchedBearish.push(t.r); });\n\n      let sentiment = \"NEUTRAL\";\n      let sentimentReasoning = \"Baseline monitoring trigger: Ongoing operational development, sector-wide baseline trend, or corporate filing to track for subsequent quarterly performance.\";\n\n      if (matchedBullish.length > matchedBearish.length) {\n        sentiment = \"BULLISH\";\n        sentimentReasoning = matchedBullish.slice(0, 2).join(\" Additionally, \");\n      } else if (matchedBearish.length > matchedBullish.length) {\n        sentiment = \"BEARISH\";\n        sentimentReasoning = matchedBearish.slice(0, 2).join(\" Additionally, \");\n      }\n\n      const detectedTickers = [];\n      const upperText = (story.headline + \" \" + story.brief_details + \" \" + (story.bullet_points || []).join(\" \")).toUpperCase();\n      tickerDictionary.forEach(t => {\n        if (new RegExp(`\\\\b${t}\\\\b`, 'i').test(upperText)) detectedTickers.push(t);\n      });\n\n      let catalyst = (story.bullet_points && story.bullet_points.length > 0) ? story.bullet_points[0] : story.brief_details.slice(0, 160) + \"...\";\n\n      return {\n        ...story,\n        id: idx + 1,\n        category: category || \"Others\",\n        sentiment,\n        sentimentReasoning,\n        tickers: [...new Set(detectedTickers)].slice(0, 3),\n        catalyst,\n        isFrontPage,\n        isOpinion\n      };\n    }\n\n    function parseIpoItem(s, idx) {\n      const h = s.headline;\n      const d = s.brief_details;\n      const combined = (h + \" \" + d).toLowerCase();\n\n      let company = h.replace(/public announcement|basis of allotment|files ipo papers|files draft ipo papers|ipo subscribed|files for|shelves|amid market uncertainty/gi, '').trim();\n      company = company.replace(/^(biscuit maker|nine firms filing ipo papers with sebi:|after reverse flip to india: cfo)/gi, '').trim();\n      if (company.length > 32) company = company.slice(0, 32) + '...';\n\n      let size = \"Not Disclosed\";\n      const sizeMatch = (h + \" \" + d).match(/(?:\u20b9|\u2090|rs\\.?)\\s?([\\d,]+(?:\\.\\d+)?)\\s?(?:cr|crore|lakh)/i);\n      if (sizeMatch) size = `\u20b9${sizeMatch[1]} Cr`;\n      else if (combined.includes(\"fresh issue\")) size = \"Fresh Issue\";\n      else if (combined.includes(\"sme\")) size = \"SME Issue\";\n\n      // Detect Target Listing Exchange\n      let exchange = \"NSE / BSE Mainboard\";\n      if (combined.includes(\"sme\") || combined.includes(\"emerge\")) {\n        exchange = \"NSE Emerge / BSE SME\";\n      } else if (combined.includes(\"bse only\") || combined.includes(\"bse startup\")) {\n        exchange = \"BSE Only\";\n      }\n\n      let stage = \"\ud83d\udccb DRHP Filed\";\n      let stageBadge = \"bg-amber-50 text-amber-800 border-amber-200 dark:bg-amber-950/40 dark:text-amber-300\";\n      let filterTag = \"DRHP\";\n\n      if (combined.includes(\"subscribed\")) {\n        stage = \"\ud83d\udcc8 Active Bidding\";\n        stageBadge = \"bg-emerald-50 text-emerald-800 border-emerald-200 dark:bg-emerald-950/40 dark:text-emerald-300\";\n        filterTag = \"BIDDING\";\n      } else if (combined.includes(\"allotment\") || combined.includes(\"basis\")) {\n        stage = \"\ud83c\udfdb\ufe0f Allotment Out\";\n        stageBadge = \"bg-blue-50 text-blue-800 border-blue-200 dark:bg-blue-950/40 dark:text-blue-300\";\n        filterTag = \"NOTICES\";\n      } else if (combined.includes(\"shelve\") || combined.includes(\"delay\")) {\n        stage = \"\u23f8\ufe0f Deferred\";\n        stageBadge = \"bg-rose-50 text-rose-800 border-rose-200 dark:bg-rose-950/40 dark:text-rose-300\";\n        filterTag = \"DRHP\";\n      } else if (combined.includes(\"announcement\") || combined.includes(\"notice\")) {\n        stage = \"\ud83d\udce2 Public Issue Notice\";\n        stageBadge = \"bg-purple-50 text-purple-800 border-purple-200 dark:bg-purple-950/40 dark:text-purple-300\";\n        filterTag = \"NOTICES\";\n      }\n\n      let demand = \"Filing Stage\";\n      const subMatch = (h + \" \" + d).match(/subscribed\\s+([\\d\\.]+)\\s+(?:times|x)/i);\n      const subPctMatch = (h + \" \" + d).match(/subscribed\\s+([\\d\\.]+%)/i);\n      if (subMatch) demand = `${subMatch[1]}x Subscribed`;\n      else if (subPctMatch) demand = `${subPctMatch[1]} Subscribed`;\n      else if (stage.includes(\"Allotment\")) demand = \"Completed\";\n\n      return {\n        id: idx + 1,\n        headline: h,\n        company: company || h.slice(0, 25),\n        size,\n        exchange,\n        stage,\n        stageBadge,\n        filterTag,\n        demand,\n        details: d,\n        source: s.page_numbers || \"FE / BS\"\n      };\n    }\n\n    async function fetchDates() {\n      try {\n        const res = await fetch(`/api/dates?t=${Date.now()}`);\n        if (res.ok) {\n          availableDates = await res.json();\n          const select = document.getElementById(\"edition-date-select\");\n          if (availableDates && availableDates.length > 0) {\n            select.innerHTML = \"\";\n            availableDates.forEach((d, idx) => {\n              const opt = document.createElement(\"option\");\n              opt.value = d;\n              opt.textContent = idx === 0 ? `${d} (Latest)` : d;\n              opt.className = \"bg-slate-900 text-white font-mono\";\n              select.appendChild(opt);\n            });\n            if (rawReport && rawReport.edition_date) {\n              select.value = rawReport.edition_date;\n              document.getElementById(\"calendar-picker\").value = rawReport.edition_date;\n            } else {\n              document.getElementById(\"calendar-picker\").value = availableDates[0];\n            }\n          }\n        }\n      } catch (e) {}\n    }\n\n    function navigateDate(dir) {\n      if (!availableDates || availableDates.length === 0) return;\n      currentDateIndex += dir;\n      if (currentDateIndex < 0) currentDateIndex = 0;\n      if (currentDateIndex >= availableDates.length) currentDateIndex = availableDates.length - 1;\n      const target = availableDates[currentDateIndex];\n      document.getElementById(\"edition-date-select\").value = target;\n      document.getElementById(\"calendar-picker\").value = target;\n      loadData(target);\n    }\n\n    function onCalendarSelect(val) {\n      if (!val) return;\n      document.getElementById(\"edition-date-select\").value = val;\n      loadData(val);\n    }\n\n    async function onDateChange(selectedDate) {\n      document.getElementById(\"calendar-picker\").value = selectedDate;\n      await loadData(selectedDate);\n    }\n\n    async function loadData(targetDate = null) {\n      try {\n        const endpoint = targetDate ? `/api/report?date=${targetDate}&t=${Date.now()}` : `/api/report?t=${Date.now()}`;\n        const res = await fetch(endpoint);\n        if (!res.ok) throw new Error(\"Failed\");\n        rawReport = await res.json();\n      } catch (e) {\n        try {\n          const fallbackUrl = targetDate \n            ? `https://pub-c81167dd545d49d0a2cd964a8bd6a1cd.r2.dev/reports/news_report_unified_${targetDate}.json?t=${Date.now()}`\n            : `https://pub-c81167dd545d49d0a2cd964a8bd6a1cd.r2.dev/reports/news_report_unified_latest.json?t=${Date.now()}`;\n          const res = await fetch(fallbackUrl);\n          rawReport = await res.json();\n        } catch (err) {}\n      }\n\n      if (rawReport && rawReport.major_stories) {\n        const edDate = rawReport.edition_date;\n        const dateInput = document.getElementById(\"calendar-picker\");\n        if (dateInput && edDate) dateInput.value = edDate;\n        \n        const dateSelect = document.getElementById(\"edition-date-select\");\n        if (dateSelect && edDate) {\n          let found = false;\n          for (let opt of dateSelect.options) {\n            if (opt.value === edDate) { opt.selected = true; found = true; break; }\n          }\n          if (!found) {\n            const opt = document.createElement(\"option\");\n            opt.value = edDate;\n            opt.textContent = `${edDate} (Latest)`;\n            opt.selected = true;\n            dateSelect.prepend(opt);\n          }\n        }\n\n        stories = rawReport.major_stories\n          .map((s, idx) => parseStory(s, idx))\n          .filter(Boolean);\n\n        const rawIpos = stories.filter(s => s.category === \"IPO\");\n        ipoList = rawIpos.map((s, idx) => parseIpoItem(s, idx));\n        initMetrics();\n      }\n    }\n\n    function initMetrics() {\n      // Core All News strictly excludes IPO, Corporate Events, Corporate Appointments, and Opinions\n      const coreStories = stories.filter(s => s.category !== \"IPO\" && s.category !== \"Corporate Events\" && s.category !== \"Corporate Appointments\" && !s.isOpinion);\n      const totalIpos = ipoList.length;\n      const anchorCount = coreStories.filter(s => s.isFrontPage).length;\n      const corpEventsCount = stories.filter(s => s.category === \"Corporate Events\").length;\n      const corpApptsCount = stories.filter(s => s.category === \"Corporate Appointments\").length;\n      const corpCount = corpEventsCount + corpApptsCount;\n      const opinionsCount = stories.filter(s => s.isOpinion).length;\n\n      document.getElementById(\"top-total-count\").textContent = stories.length;\n      document.getElementById(\"tab-feed-count\").textContent = coreStories.length;\n      document.getElementById(\"tab-ipo-count\").textContent = totalIpos;\n      document.getElementById(\"tab-anchor-count\").textContent = anchorCount;\n      document.getElementById(\"tab-corp-count\").textContent = corpCount;\n      const tabEvents = document.getElementById(\"tab-events-count\");\n      if (tabEvents) tabEvents.textContent = corpEventsCount;\n      const tabAppts = document.getElementById(\"tab-appointments-count\");\n      if (tabAppts) tabAppts.textContent = corpApptsCount;\n      document.getElementById(\"tab-opinions-count\").textContent = opinionsCount;\n\n      let bCount = 0, rCount = 0;\n      coreStories.forEach(s => {\n        if (s.sentiment === \"BULLISH\") bCount++;\n        else if (s.sentiment === \"BEARISH\") rCount++;\n      });\n      document.getElementById(\"feed-count-all\").textContent = coreStories.length;\n      document.getElementById(\"feed-count-bullish\").textContent = bCount;\n      document.getElementById(\"feed-count-bearish\").textContent = rCount;\n\n      // Render Source Pipeline Health\n      const healthContainer = document.getElementById(\"source-health-container\");\n      const alertBanner = document.getElementById(\"source-alert-banner\");\n      const alertText = document.getElementById(\"source-alert-text\");\n\n      if (healthContainer) {\n        healthContainer.innerHTML = \"\";\n        const statuses = (rawReport && rawReport.source_statuses) || {};\n        \n        let hasFailure = false;\n        let failureDetails = [];\n\n        const feStatus = statuses.financial_express || \"\u2705 FE (Active)\";\n        const bsStatus = statuses.business_standard || (stories.some(s => (s.page_numbers || \"\").includes(\"BS\")) ? \"\u2705 BS (Active)\" : \"\u274c BS (Session Expired)\");\n\n        const fePill = document.createElement(\"span\");\n        fePill.className = feStatus.includes(\"\u2705\") \n          ? \"px-1.5 py-0.2 rounded bg-slate-900 border border-slate-700 text-slate-300 font-bold\" \n          : \"px-1.5 py-0.2 rounded bg-rose-500/20 border border-rose-500/40 text-rose-300 font-bold\";\n        fePill.textContent = `FE: ${feStatus.includes(\"\u2705\") ? '\u2705' : '\u274c'}`;\n        fePill.title = `Financial Express: ${feStatus}`;\n        healthContainer.appendChild(fePill);\n\n        const bsPill = document.createElement(\"span\");\n        const bsOk = bsStatus.includes(\"\u2705\") || bsStatus.includes(\"Active\");\n        bsPill.className = bsOk \n          ? \"px-1.5 py-0.2 rounded bg-slate-900 border border-slate-700 text-slate-300 font-bold\" \n          : \"px-1.5 py-0.2 rounded bg-rose-500/20 border border-rose-500/40 text-rose-300 font-bold\";\n        bsPill.textContent = `BS: ${bsOk ? '\u2705' : '\u274c'}`;\n        bsPill.title = `Business Standard: ${bsStatus}`;\n        healthContainer.appendChild(bsPill);\n\n        if (!bsOk) {\n          hasFailure = true;\n          failureDetails.push(\"Business Standard subscriber session expired or was not authenticated. Showing Financial Express news.\");\n        }\n        if (!feStatus.includes(\"\u2705\")) {\n          hasFailure = true;\n          failureDetails.push(\"Financial Express edition failed to download.\");\n        }\n\n        if (hasFailure && alertBanner && alertText) {\n          alertText.innerHTML = `<b>Edition Notice:</b> ${failureDetails.join(\" \u00b7 \")}`;\n          alertBanner.classList.remove(\"hidden\");\n        } else if (alertBanner) {\n          alertBanner.classList.add(\"hidden\");\n        }\n      }\n\n      renderStocksFocusSidebar();\n      renderFeedList();\n      renderIpoTable();\n    }\n\n    // ================= FILTER LOGIC =================\n    function getFilteredStories() {\n      const rawQuery = document.getElementById(\"global-search\").value.trim().toLowerCase();\n      const queryTokens = rawQuery ? rawQuery.split(/\\s+/).filter(Boolean) : [];\n      \n      return stories.filter(s => {\n        const searchableText = (\n          s.headline + \" \" + \n          s.brief_details + \" \" + \n          (s.bullet_points || []).join(\" \") + \" \" + \n          s.category + \" \" + \n          s.page_numbers + \" \" + \n          s.tickers.join(\" \")\n        ).toLowerCase();\n\n        const matchQuery = queryTokens.length === 0 || queryTokens.every(tok => searchableText.includes(tok));\n        \n        let matchSec = true;\n        if (selectedFeedCategory === \"ALL\") {\n          matchSec = s.category !== \"IPO\" && s.category !== \"Corporate Events\" && s.category !== \"Corporate Appointments\" && !s.isOpinion;\n        } else if (selectedFeedCategory === \"ANCHOR\") {\n          matchSec = s.isFrontPage && s.category !== \"IPO\" && s.category !== \"Corporate Events\" && s.category !== \"Corporate Appointments\" && !s.isOpinion;\n        } else if (selectedFeedCategory === \"CORPORATE_ALL\") {\n          matchSec = s.category === \"Corporate Events\" || s.category === \"Corporate Appointments\";\n        } else if (selectedFeedCategory === \"EVENTS\") {\n          matchSec = s.category === \"Corporate Events\";\n        } else if (selectedFeedCategory === \"APPOINTMENTS\") {\n          matchSec = s.category === \"Corporate Appointments\";\n        } else if (selectedFeedCategory === \"OPINIONS\") {\n          matchSec = s.isOpinion;\n        } else if (selectedFeedCategory === \"Others\") {\n          matchSec = s.category === \"Others\" && !s.isOpinion;\n        } else {\n          matchSec = s.category === selectedFeedCategory && !s.isOpinion;\n        }\n\n        const matchSent = selectedFeedSentiment === \"ALL\" || s.sentiment === selectedFeedSentiment;\n        const matchTicker = !activeTickerFilter || s.tickers.includes(activeTickerFilter);\n\n        return matchSec && matchSent && matchTicker && matchQuery;\n      });\n    }\n\n    function navigateStory(dir) {\n      const displayed = getFilteredStories();\n      const total = displayed.length;\n      if (total === 0) return;\n      selectedStoryIndex += dir;\n      if (selectedStoryIndex < 0) selectedStoryIndex = 0;\n      if (selectedStoryIndex >= total) selectedStoryIndex = total - 1;\n      currentFeedPage = Math.floor(selectedStoryIndex / FEED_PAGE_SIZE) + 1;\n      renderFeedList();\n    }\n\n    function changeFeedPage(delta) {\n      const displayed = getFilteredStories();\n      const totalPages = Math.ceil(displayed.length / FEED_PAGE_SIZE) || 1;\n      const targetPage = currentFeedPage + delta;\n      if (targetPage >= 1 && targetPage <= totalPages) {\n        currentFeedPage = targetPage;\n        selectedStoryIndex = (currentFeedPage - 1) * FEED_PAGE_SIZE;\n        renderFeedList();\n      }\n    }\n\n    // ================= SEARCH HANDLING =================\n    function onSearchInput() {\n      const val = document.getElementById(\"global-search\").value.trim();\n      currentSearchQuery = val;\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n      document.getElementById(\"clear-search-btn\").classList.toggle(\"hidden\", val.length === 0);\n      \n      if (currentView === \"ipo\") {\n        renderIpoTable();\n      } else if (currentLayoutMode === \"split\") {\n        renderFeedList();\n      } else {\n        renderMatrixTable();\n      }\n    }\n\n    function clearSearch() {\n      document.getElementById(\"global-search\").value = \"\";\n      currentSearchQuery = \"\";\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n      document.getElementById(\"clear-search-btn\").classList.add(\"hidden\");\n      if (currentView === \"ipo\") renderIpoTable();\n      else if (currentLayoutMode === \"split\") renderFeedList();\n      else renderMatrixTable();\n    }\n\n    // ================= RIGHT HAND SIDEBAR: STOCKS IN FOCUS (EXCLUDES IPOS) =================\n    function renderStocksFocusSidebar() {\n      const list = document.getElementById(\"stocks-focus-list\");\n      list.innerHTML = \"\";\n\n      const counts = {};\n      stories.forEach(s => {\n        s.tickers.forEach(t => counts[t] = (counts[t] || 0) + 1);\n      });\n\n      const sorted = Object.keys(counts).sort((a,b) => counts[b] - counts[a]);\n\n      sorted.forEach(t => {\n        const isSelected = activeTickerFilter === t;\n        const btn = document.createElement(\"button\");\n        btn.className = `px-2.5 py-1 rounded-md text-[11.5px] font-mono font-bold transition-all shadow-2xs ${isSelected ? 'bg-brand-600 text-white shadow-xs' : 'bg-slate-100 dark:bg-[#141A2E] border border-slate-200 dark:border-slate-800 text-slate-700 dark:text-slate-300 hover:border-brand-500 hover:text-brand-600 dark:hover:text-brand-400'}`;\n        btn.textContent = `${t} (${counts[t]})`;\n        btn.onclick = () => {\n          activeTickerFilter = activeTickerFilter === t ? null : t;\n          selectedStoryIndex = 0;\n          currentFeedPage = 1;\n          document.getElementById(\"clear-ticker-filter\").classList.toggle(\"hidden\", !activeTickerFilter);\n          renderStocksFocusSidebar();\n          if (currentLayoutMode === \"split\") renderFeedList();\n          else renderMatrixTable();\n        };\n        list.appendChild(btn);\n      });\n    }\n\n    function clearTickerFilter() {\n      activeTickerFilter = null;\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n      document.getElementById(\"clear-ticker-filter\").classList.add(\"hidden\");\n      renderStocksFocusSidebar();\n      if (currentLayoutMode === \"split\") renderFeedList();\n      else renderMatrixTable();\n    }\n\n    function setFeedSentiment(sent) {\n      selectedFeedSentiment = sent;\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n      document.querySelectorAll(\"[id^='sent-']\").forEach(b => {\n        b.className = \"px-2.5 py-0.5 rounded text-slate-400 hover:bg-slate-800\";\n      });\n      const el = document.getElementById(`sent-${sent.toLowerCase()}`);\n      if (el) {\n        el.className = sent === \"BULLISH\" \n          ? \"px-2.5 py-0.5 rounded bg-emerald-600 text-white shadow-xs\" \n          : sent === \"BEARISH\" \n          ? \"px-2.5 py-0.5 rounded bg-rose-600 text-white shadow-xs\" \n          : \"px-2.5 py-0.5 rounded bg-slate-800 text-white shadow-xs\";\n      }\n      if (currentLayoutMode === \"split\") renderFeedList();\n      else renderMatrixTable();\n    }\n\n    // ================= FEED LIST & ACTIVE STORY DETAIL (MAX 12 1-LINER STORIES PER PAGE) =================\n    function renderFeedList() {\n      const rawQuery = document.getElementById(\"global-search\").value.trim().toLowerCase();\n      const queryTokens = rawQuery ? rawQuery.split(/\\s+/).filter(Boolean) : [];\n      \n      const displayed = getFilteredStories();\n      const totalStories = displayed.length;\n      const totalPages = Math.ceil(totalStories / FEED_PAGE_SIZE) || 1;\n\n      if (currentFeedPage > totalPages) currentFeedPage = totalPages;\n      if (currentFeedPage < 1) currentFeedPage = 1;\n\n      const startIndex = (currentFeedPage - 1) * FEED_PAGE_SIZE;\n      const endIndex = Math.min(startIndex + FEED_PAGE_SIZE, totalStories);\n      const pageStories = displayed.slice(startIndex, endIndex);\n\n      // Header indicator\n      const countBadge = document.getElementById(\"feed-list-count\");\n      if (countBadge) {\n        countBadge.textContent = totalStories > 0 ? `${startIndex + 1}-${endIndex} of ${totalStories}` : `0 Stories`;\n      }\n\n      // Pagination Controls\n      const pagInfo = document.getElementById(\"feed-pagination-info\");\n      if (pagInfo) {\n        pagInfo.textContent = `Page ${currentFeedPage} / ${totalPages} (${totalStories})`;\n      }\n      const prevBtn = document.getElementById(\"feed-prev-page\");\n      const nextBtn = document.getElementById(\"feed-next-page\");\n      if (prevBtn) {\n        prevBtn.disabled = currentFeedPage <= 1;\n        prevBtn.className = currentFeedPage <= 1 \n          ? \"px-2 py-0.5 rounded bg-slate-100 dark:bg-slate-800 text-[10.5px] font-bold text-slate-400 dark:text-slate-600 border border-slate-200 dark:border-slate-800 cursor-not-allowed opacity-50\"\n          : \"px-2 py-0.5 rounded bg-white dark:bg-slate-800 hover:bg-indigo-50 text-[10.5px] font-bold text-slate-900 dark:text-slate-200 border border-slate-300 dark:border-slate-700 shadow-2xs cursor-pointer\";\n      }\n      if (nextBtn) {\n        nextBtn.disabled = currentFeedPage >= totalPages;\n        nextBtn.className = currentFeedPage >= totalPages \n          ? \"px-2 py-0.5 rounded bg-slate-100 dark:bg-slate-800 text-[10.5px] font-bold text-slate-400 dark:text-slate-600 border border-slate-200 dark:border-slate-800 cursor-not-allowed opacity-50\"\n          : \"px-2 py-0.5 rounded bg-white dark:bg-slate-800 hover:bg-indigo-50 text-[10.5px] font-bold text-slate-900 dark:text-slate-200 border border-slate-300 dark:border-slate-700 shadow-2xs cursor-pointer\";\n      }\n\n      const listContainer = document.getElementById(\"feed-list-container\");\n      listContainer.innerHTML = \"\";\n\n      if (totalStories === 0) {\n        listContainer.innerHTML = `\n          <div class=\"p-8 text-center text-slate-400\">\n            <p class=\"text-base font-bold text-slate-600 dark:text-slate-300\">No news stories found</p>\n            <p class=\"text-[12.5px] mt-1\">Try broadening your search term or selecting another section.</p>\n            ${rawQuery ? `<button onclick=\"clearSearch()\" class=\"mt-3 px-3 py-1 bg-brand-600 text-white rounded-md text-xs font-bold\">Clear Search</button>` : ''}\n          </div>\n        `;\n        document.getElementById(\"feed-detail-container\").innerHTML = `<div class=\"p-8 text-center text-slate-400 text-[13.5px]\">Select a story to view analysis.</div>`;\n        return;\n      }\n\n      if (selectedStoryIndex < startIndex || selectedStoryIndex >= endIndex) {\n        selectedStoryIndex = startIndex;\n      }\n\n      pageStories.forEach((s, localIdx) => {\n        const globalIdx = startIndex + localIdx;\n        const isSelected = globalIdx === selectedStoryIndex;\n        const numStr = (globalIdx + 1).toString().padStart(2, '0');\n        const dot = s.sentiment === \"BULLISH\" ? \"bg-emerald-500\" : s.sentiment === \"BEARISH\" ? \"bg-rose-500\" : \"bg-slate-400\";\n\n        const btn = document.createElement(\"button\");\n        btn.className = `w-full text-left px-2.5 py-1.5 rounded-lg transition-all flex items-center gap-2 border shadow-2xs mb-1.5 last:mb-0 ${isSelected ? 'bg-indigo-50/95 dark:bg-indigo-950/80 border-indigo-500 shadow-xs font-bold text-indigo-950 dark:text-white' : 'bg-white dark:bg-[#0D1322] border-slate-200/90 dark:border-slate-800/80 hover:border-slate-300 dark:hover:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-800/50 text-slate-800 dark:text-slate-200'}`;\n        btn.onclick = () => {\n          selectedStoryIndex = globalIdx;\n          renderFeedList();\n          // On mobile screens (iPhone / tablet), smoothly scroll reader panel into view\n          if (window.innerWidth < 1024) {\n            const detailWrapper = document.getElementById(\"feed-detail-wrapper\");\n            if (detailWrapper) {\n              detailWrapper.scrollIntoView({ behavior: 'smooth', block: 'start' });\n            }\n          }\n        };\n\n        btn.innerHTML = `\n          <span class=\"shrink-0 text-[10px] font-mono font-bold text-slate-400 dark:text-slate-500 tabular-nums w-4\">${numStr}</span>\n          <span class=\"w-1.5 h-1.5 rounded-full shrink-0 ${dot}\"></span>\n          <h4 class=\"text-[12px] font-bold tracking-tight truncate flex-1 min-w-0 ${isSelected ? 'text-indigo-950 dark:text-white font-extrabold' : 'text-slate-900 dark:text-slate-100'}\" title=\"${escapeQuotes(s.headline)}\">\n            ${highlightSearchTokens(s.headline, queryTokens)}\n          </h4>\n        `;\n        listContainer.appendChild(btn);\n      });\n\n      renderActiveStoryDetail(displayed[selectedStoryIndex], queryTokens);\n    }\n\n    // Helper: Build High-Contrast Infographic KPI Badges Grid\n    function buildKpiCardsHtml(story) {\n      if (!story) return \"\";\n      let kpis = story.kpis || [];\n\n      if (kpis.length === 0) {\n        const full = (story.headline + \" \" + story.brief_details + \" \" + (story.bullet_points || []).join(\" \"));\n        const found = [];\n\n        // 1. Currency patterns: \u20b919,090 cr, \u20b911.62 lakh cr, $29.36 billion, etc.\n        const curMatches = full.match(/(?:\u20b9|rs\\.?|\\$)\\s?[\\d,]+(?:\\.\\d+)?\\s?(?:lakh\\s+crore|crore|cr|lakh|billion|bn|million|mn)/gi) || [];\n        curMatches.forEach(m => {\n          if (!found.some(f => f.value.toLowerCase() === m.toLowerCase()) && found.length < 4) {\n            found.push({ label: \"FINANCIAL SCALE\", value: m.trim(), context: \"Key Financial Value\" });\n          }\n        });\n\n        // 2. Percentage patterns: 48%, 51%, 1.5%, 5% + 3%, etc.\n        const pctMatches = full.match(/\\b\\d+(?:\\.\\d+)?%\\b/g) || [];\n        pctMatches.forEach(m => {\n          if (!found.some(f => f.value === m) && found.length < 4) {\n            found.push({ label: \"GROWTH / SHARE\", value: m.trim(), context: \"Impact Percentage\" });\n          }\n        });\n\n        // 3. Jobs / Counts / Volume: 167,000 jobs, etc.\n        const jobMatch = full.match(/([\\d,]+)\\s*(?:jobs|direct and indirect jobs|workers|units|tonnes|ton|mw|gw)/i);\n        if (jobMatch && found.length < 4) {\n          found.push({ label: \"VOLUME / IMPACT\", value: jobMatch[0].trim(), context: \"Scale / Volume Output\" });\n        }\n\n        if (found.length > 0) {\n          kpis = found.slice(0, 4);\n        }\n      }\n\n      if (kpis.length === 0) return \"\";\n\n      return `\n        <div class=\"my-2 rounded-xl bg-gradient-to-br from-indigo-950/15 via-slate-900/10 to-blue-950/15 dark:from-[#0F1629] dark:to-[#0B1020] p-2.5 border border-indigo-200/80 dark:border-indigo-900/60 shadow-2xs\">\n          <div class=\"flex items-center justify-between pb-1.5 mb-2 border-b border-indigo-100 dark:border-slate-800/80\">\n            <span class=\"text-[10.5px] font-mono font-black uppercase tracking-wider text-indigo-700 dark:text-indigo-400 flex items-center gap-1.5\">\n              <span>\ud83d\udcca</span> <span>SCALE OF IMPACT & INFOGRAPHIC KPIS</span>\n            </span>\n            <span class=\"text-[9.5px] font-mono font-bold text-slate-500 dark:text-slate-400\">Quick Metrics</span>\n          </div>\n          <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2\">\n            ${kpis.map((k, i) => {\n              const colors = [\n                'from-blue-500/10 to-indigo-500/10 border-blue-300 dark:border-blue-800 text-blue-700 dark:text-blue-300',\n                'from-emerald-500/10 to-teal-500/10 border-emerald-300 dark:border-emerald-800 text-emerald-700 dark:text-emerald-300',\n                'from-amber-500/10 to-orange-500/10 border-amber-300 dark:border-amber-800 text-amber-700 dark:text-amber-300',\n                'from-purple-500/10 to-pink-500/10 border-purple-300 dark:border-purple-800 text-purple-700 dark:text-purple-300'\n              ];\n              const colorClass = colors[i % colors.length];\n              return `\n                <div class=\"p-2 rounded-lg bg-gradient-to-br ${colorClass} border flex flex-col justify-between shadow-2xs\">\n                  <span class=\"text-[9.5px] font-mono font-bold uppercase tracking-wider text-slate-600 dark:text-slate-400 truncate\">${escapeQuotes(k.label || 'METRIC')}</span>\n                  <span class=\"text-[15.5px] sm:text-[16.5px] font-mono font-black tracking-tight mt-0.5\">${escapeQuotes(k.value)}</span>\n                  ${k.context ? `<span class=\"text-[9px] font-mono text-slate-500 dark:text-slate-400 truncate mt-0.5\">${escapeQuotes(k.context)}</span>` : ''}\n                </div>\n              `;\n            }).join('')}\n          </div>\n        </div>\n      `;\n    }\n\n    // Helper: Build Structured Key Quantitative Data Table from Bullet Points\n    function buildMetricsTableHtml(bullets) {\n      if (!bullets || bullets.length === 0) return \"\";\n      \n      const rows = [];\n      bullets.forEach(b => {\n        if (b.includes(\":\") || b.includes(\"\u20b9\") || b.includes(\"%\") || b.includes(\"Rs\") || b.includes(\"capped at\") || b.includes(\"lowered to\") || b.includes(\"threshold\")) {\n          let param = \"\", val = \"\";\n          if (b.includes(\":\")) {\n            const parts = b.split(\":\");\n            param = parts[0].trim();\n            val = parts.slice(1).join(\":\").trim();\n          } else {\n            param = b.slice(0, 45) + \"...\";\n            val = b;\n          }\n          if (param && val) {\n            rows.push({ param, val });\n          }\n        }\n      });\n\n      if (rows.length >= 2) {\n        return `\n          <div class=\"mt-2 rounded-lg border border-slate-200 dark:border-slate-800 overflow-hidden shadow-2xs\">\n            <div class=\"bg-slate-100/90 dark:bg-[#141A2E] px-3 py-1.5 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between\">\n              <span class=\"text-[11px] font-mono font-bold uppercase tracking-wider text-slate-700 dark:text-slate-300 flex items-center gap-1.5\">\n                <span>\ud83d\udccb</span> <span>Key Quantitative Data & Regulatory Thresholds</span>\n              </span>\n            </div>\n            <table class=\"w-full text-left border-collapse text-[12.5px]\">\n              <tbody class=\"divide-y divide-slate-100 dark:divide-slate-800/80 font-mono\">\n                ${rows.slice(0, 5).map(r => `\n                  <tr class=\"table-row-hover\">\n                    <td class=\"py-1.5 px-3 font-bold text-slate-800 dark:text-slate-200 bg-slate-50/50 dark:bg-slate-900/30 w-1/3\">${escapeQuotes(r.param)}</td>\n                    <td class=\"py-1.5 px-3 font-medium text-slate-950 dark:text-white\">${highlightNumbers(escapeQuotes(r.val))}</td>\n                  </tr>\n                `).join('')}\n              </tbody>\n            </table>\n          </div>\n        `;\n      }\n      return \"\";\n    }\n\n    function renderActiveStoryDetail(story, queryTokens = []) {\n      const container = document.getElementById(\"feed-detail-container\");\n      if (!story) return;\n\n      const isBullish = story.sentiment === \"BULLISH\";\n      const isBearish = story.sentiment === \"BEARISH\";\n      \n      const sentBadge = isBullish \n        ? `<span class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-extrabold bg-emerald-100 text-emerald-950 border border-emerald-300 dark:bg-emerald-950/70 dark:text-emerald-200\">\ud83d\udfe2 BULLISH</span>`\n        : isBearish \n        ? `<span class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-extrabold bg-rose-100 text-rose-950 border border-rose-300 dark:bg-rose-950/70 dark:text-rose-200\">\ud83d\udd34 BEARISH</span>`\n        : `<span class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-extrabold bg-slate-200 text-slate-900 border border-slate-300 dark:bg-slate-800 dark:text-slate-200\">\u26aa NEUTRAL</span>`;\n\n      const reasonBoxBorder = isBullish \n        ? \"border-emerald-300/90 bg-emerald-50/80 dark:bg-[#092318] dark:border-emerald-800/90\" \n        : isBearish \n        ? \"border-rose-300/90 bg-rose-50/80 dark:bg-[#250C12] dark:border-rose-800/90\" \n        : \"border-slate-300 bg-slate-50/90 dark:bg-slate-900/70 dark:border-slate-800\";\n\n      const reasonTitleColor = isBullish \n        ? \"text-emerald-950 dark:text-emerald-300 font-extrabold\" \n        : isBearish \n        ? \"text-rose-950 dark:text-rose-300 font-extrabold\" \n        : \"text-slate-950 dark:text-slate-300 font-extrabold\";\n\n      const tickerBadges = story.tickers.map(t => `<span class=\"px-2 py-0.5 text-[11px] font-mono font-bold rounded-md bg-indigo-50 text-indigo-900 border border-indigo-200 dark:bg-indigo-950/60 dark:text-indigo-200\">${t}</span>`).join('');\n      const kpisHtml = buildKpiCardsHtml(story);\n      const metricsTableHtml = buildMetricsTableHtml(story.bullet_points);\n\n      // Break brief details into short punchy sentences (NO paragraph walls)\n      const briefSentences = (story.brief_details || \"\").split(/(?<=[.?!])\\s+/).filter(Boolean);\n\n      container.innerHTML = `\n        <!-- Mobile Fast Navigation Bar -->\n        <div class=\"lg:hidden flex items-center justify-between pb-1 mb-1 border-b border-slate-200 dark:border-slate-800\">\n          <button onclick=\"window.scrollTo({ top: 0, behavior: 'smooth' })\" class=\"text-[11.5px] font-mono font-bold text-indigo-600 dark:text-indigo-400 flex items-center gap-1 py-1 px-1.5 rounded bg-indigo-50 dark:bg-indigo-950/50\">\n            <span>\u25b2 Back to Headlines</span>\n          </button>\n          <span class=\"text-[10.5px] font-mono text-slate-400\">Story #${story.id}</span>\n        </div>\n\n        <div class=\"flex items-center justify-between gap-1.5 flex-wrap pb-1.5 border-b border-slate-200 dark:border-slate-800\">\n          <div class=\"flex items-center gap-1.5\">\n            <span class=\"text-[11px] font-mono font-extrabold px-2.5 py-0.5 rounded bg-slate-200 text-slate-950 dark:bg-slate-800 dark:text-white\">${story.category}</span>\n            ${story.isFrontPage ? `<span class=\"text-[10px] font-mono font-extrabold px-2 py-0.5 rounded bg-amber-200 text-amber-950 dark:bg-amber-950/80 dark:text-amber-200\">\ud83d\udcf0 PAGE 1 ANCHOR</span>` : ''}\n            <span class=\"text-[11.5px] text-slate-600 dark:text-slate-400 font-mono font-bold\">${story.page_numbers}</span>\n          </div>\n          <div class=\"flex items-center gap-1.5\">\n            ${sentBadge}\n            <button onclick=\"copyToClipboard('${escapeQuotes(story.headline + '\\\\n\\\\n' + story.brief_details)}')\" class=\"text-[11px] text-slate-800 hover:text-slate-950 dark:text-slate-200 dark:hover:text-white font-mono flex items-center gap-1 font-bold px-2 py-0.5 rounded border border-slate-300 dark:border-slate-700 bg-white dark:bg-[#141A2E] shadow-2xs\" title=\"Copy story summary\">\n              \ud83d\udccb Copy\n            </button>\n          </div>\n        </div>\n\n        <h1 class=\"text-[18px] sm:text-[20px] font-black text-slate-950 dark:text-white leading-tight tracking-tight mt-0.5 mb-1\">${highlightSearchTokens(highlightNumbers(story.headline), queryTokens)}</h1>\n\n        ${story.tickers.length > 0 ? `\n          <div class=\"flex items-center gap-1.5 flex-wrap my-0.5\">\n            <span class=\"text-[10.5px] font-mono text-slate-600 dark:text-slate-400 font-bold\">STOCKS:</span>\n            ${tickerBadges}\n          </div>\n        ` : ''}\n\n        <!-- \ud83d\udcca 1. INFOGRAPHIC KPI SCORECARD / METRICS GRID (TEAL / CYAN BOX) -->\n        ${kpisHtml}\n\n        <!-- \u26a1 2. EXECUTIVE GIST (INDIGO / BLUE BOX) -->\n        <div class=\"mt-1.5 rounded-lg border border-indigo-300/80 dark:border-indigo-800/80 bg-indigo-50/70 dark:bg-[#10182E] p-2.5 shadow-2xs flex flex-col gap-1.5\">\n          <div class=\"flex items-center justify-between border-b border-indigo-200/80 dark:border-slate-800/80 pb-1\">\n            <span class=\"text-[10.5px] font-mono font-black uppercase tracking-wider text-indigo-950 dark:text-indigo-300 flex items-center gap-1\">\n              <span>\u26a1</span> <span>Executive Gist (Core Takeaway)</span>\n            </span>\n            <span class=\"text-[9.5px] font-mono text-indigo-700 dark:text-indigo-400 font-bold\">Quick Read</span>\n          </div>\n          <div class=\"grid grid-cols-1 gap-1.5\">\n            ${briefSentences.map(sent => `\n              <div class=\"flex items-start gap-2 bg-white dark:bg-[#11172A] p-2 rounded-md border border-slate-200/80 dark:border-slate-800/80 text-[13px] text-slate-950 dark:text-slate-100 leading-snug font-medium\">\n                <span class=\"text-indigo-600 dark:text-indigo-400 font-black text-sm select-none\">\u25b8</span>\n                <span>${highlightSearchTokens(highlightNumbers(sent), queryTokens)}</span>\n              </div>\n            `).join('')}\n          </div>\n        </div>\n\n        <!-- \ud83d\udccb 3. STRUCTURED KEY QUANTITATIVE DATA TABLE -->\n        ${metricsTableHtml}\n\n        <!-- \ud83d\udccc 4. KEY ANALYST DATA POINTS (WARM AMBER / ORANGE BOX) -->\n        <div class=\"mt-2 rounded-lg border border-amber-300/80 dark:border-amber-800/80 bg-amber-50/70 dark:bg-[#201507] p-2.5 shadow-2xs\">\n          <div class=\"flex items-center justify-between border-b border-amber-200/80 dark:border-amber-900/60 pb-1 mb-1.5\">\n            <span class=\"text-[10.5px] font-mono font-black uppercase tracking-wider text-amber-950 dark:text-amber-300 flex items-center gap-1\">\n              <span>\ud83d\udccc</span> <span>Key Analyst Data Points</span>\n            </span>\n            <span class=\"text-[9.5px] font-mono text-amber-700 dark:text-amber-400 font-bold\">Metrics & Facts</span>\n          </div>\n          <ul class=\"space-y-1.5\">\n            ${(story.bullet_points || []).map(bp => `\n              <li class=\"flex items-start gap-2 text-[13px] text-slate-950 dark:text-slate-100 leading-snug bg-white dark:bg-[#11172A] p-2 rounded-md border border-slate-200 dark:border-slate-800 shadow-2xs\">\n                <span class=\"text-amber-600 dark:text-amber-400 font-black text-sm leading-none select-none mt-0.5\">\u203a</span>\n                <span class=\"font-normal\">${highlightSearchTokens(highlightNumbers(bp), queryTokens)}</span>\n              </li>\n            `).join('')}\n          </ul>\n        </div>\n\n        <!-- \ud83d\udca1 5. TRADER CATALYST & IMPACT RATIONALE (EMERALD / ROSE / SLATE BOX) -->\n        <div class=\"mt-2 p-2.5 rounded-lg border ${reasonBoxBorder} shadow-2xs\">\n          <div class=\"flex items-center justify-between gap-1 mb-1\">\n            <span class=\"text-[11px] font-mono uppercase tracking-wider ${reasonTitleColor} flex items-center gap-1\">\n              <span>\ud83d\udca1</span> <span>Catalyst Rationale & Trader Impact</span>\n            </span>\n            <span class=\"text-[10px] font-mono font-extrabold uppercase px-2 py-0.5 rounded ${isBullish ? 'bg-emerald-200 text-emerald-950 dark:bg-emerald-900 dark:text-emerald-200' : isBearish ? 'bg-rose-200 text-rose-950 dark:bg-rose-900 dark:text-rose-200' : 'bg-slate-200 text-slate-900 dark:bg-slate-800 dark:text-slate-200'}\">${story.sentiment} THESIS</span>\n          </div>\n          <div class=\"bg-white dark:bg-[#11172A] p-2 rounded border border-slate-200/70 dark:border-slate-800 text-[13px] text-slate-950 dark:text-slate-100 leading-snug font-medium\">\n            ${highlightSearchTokens(highlightNumbers(story.sentimentReasoning), queryTokens)}\n          </div>\n        </div>\n      `;\n    }\n\n    // ================= MASTER NEWS MATRIX TABLE RENDERING =================\n    function renderMatrixTable() {\n      const tbody = document.getElementById(\"matrix-table-body\");\n      if (!tbody) return;\n      tbody.innerHTML = \"\";\n\n      const rawQuery = document.getElementById(\"global-search\").value.trim().toLowerCase();\n      const queryTokens = rawQuery ? rawQuery.split(/\\s+/).filter(Boolean) : [];\n      const displayed = getFilteredStories();\n\n      const countEl = document.getElementById(\"matrix-table-visible-count\");\n      if (countEl) countEl.textContent = displayed.length;\n\n      if (displayed.length === 0) {\n        tbody.innerHTML = `<tr><td colspan=\"8\" class=\"py-10 text-center text-slate-400 font-medium text-[13.5px]\">No stories found matching filters.</td></tr>`;\n        return;\n      }\n\n      displayed.forEach((story, idx) => {\n        const tr = document.createElement(\"tr\");\n        tr.className = \"table-row-hover transition-colors border-b border-slate-100 dark:border-slate-800/80 cursor-pointer\";\n        const numStr = (idx + 1).toString().padStart(2, '0');\n        \n        const isBullish = story.sentiment === \"BULLISH\";\n        const isBearish = story.sentiment === \"BEARISH\";\n        const sentBadge = isBullish \n          ? `<span class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-extrabold bg-emerald-100 text-emerald-950 border border-emerald-300 dark:bg-emerald-950/70 dark:text-emerald-200 whitespace-nowrap\">\ud83d\udfe2 BULLISH</span>`\n          : isBearish \n          ? `<span class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-extrabold bg-rose-100 text-rose-950 border border-rose-300 dark:bg-rose-950/70 dark:text-rose-200 whitespace-nowrap\">\ud83d\udd34 BEARISH</span>`\n          : `<span class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-extrabold bg-slate-200 text-slate-900 border border-slate-300 dark:bg-slate-800 dark:text-slate-200 whitespace-nowrap\">\u26aa NEUTRAL</span>`;\n\n        const tickerBadges = (story.tickers || []).map(t => `<span class=\"px-1.5 py-0.2 text-[10px] font-mono font-bold rounded bg-indigo-50 text-indigo-900 border border-indigo-200 dark:bg-indigo-950/60 dark:text-indigo-200\">${t}</span>`).join(' ') || '<span class=\"text-slate-400 font-mono text-[11px]\">\u2014</span>';\n\n        tr.onclick = (e) => {\n          if (e.target.tagName !== 'BUTTON') {\n            openStoryModal(idx);\n          }\n        };\n\n        tr.innerHTML = `\n          <td class=\"py-3 px-3 font-mono text-[12px] text-slate-400 font-semibold\">${numStr}</td>\n          <td class=\"py-3 px-3.5 font-bold text-slate-900 dark:text-white max-w-sm\">\n            <div class=\"flex items-start gap-1.5\">\n              ${story.isFrontPage ? `<span class=\"shrink-0 text-[9px] font-mono font-extrabold px-1.5 py-0.2 rounded bg-amber-200 text-amber-950 dark:bg-amber-950/80 dark:text-amber-200 mt-0.5\">PAGE 1</span>` : ''}\n              <div>\n                <p class=\"text-[13.5px] leading-tight font-bold text-slate-900 dark:text-white\">${highlightSearchTokens(highlightNumbers(story.headline), queryTokens)}</p>\n                <p class=\"text-[11px] font-mono text-slate-400 truncate max-w-[280px] mt-0.5 font-normal\">${story.catalyst}</p>\n              </div>\n            </div>\n          </td>\n          <td class=\"py-3 px-3 whitespace-nowrap\">\n            <span class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-extrabold bg-slate-100 text-slate-800 dark:bg-slate-800 dark:text-slate-200 border border-slate-200 dark:border-slate-700\">\n              ${story.category}\n            </span>\n          </td>\n          <td class=\"py-3 px-3 whitespace-nowrap\">${sentBadge}</td>\n          <td class=\"py-3 px-3 font-mono text-[11.5px] text-slate-500 dark:text-slate-400 whitespace-nowrap\">${story.page_numbers}</td>\n          <td class=\"py-3 px-3 whitespace-nowrap\">${tickerBadges}</td>\n          <td class=\"py-3 px-3.5 max-w-md\">\n            <p class=\"text-[12.5px] text-slate-700 dark:text-slate-300 leading-snug line-clamp-2 font-normal\">\n              ${highlightSearchTokens(highlightNumbers(story.brief_details), queryTokens)}\n            </p>\n          </td>\n          <td class=\"py-3 px-3 text-center whitespace-nowrap\">\n            <button onclick=\"openStoryModal(${idx})\" class=\"px-2.5 py-1 rounded-md border border-brand-200 dark:border-slate-700 bg-brand-50/80 dark:bg-[#182035] hover:bg-brand-600 hover:text-white text-brand-700 dark:text-brand-300 text-[11px] font-mono font-bold transition-all shadow-2xs\">\n              \u2139\ufe0f Details\n            </button>\n          </td>\n        `;\n        tbody.appendChild(tr);\n      });\n    }\n\n    function openStoryModal(idx) {\n      const displayed = getFilteredStories();\n      const story = displayed[idx];\n      if (!story) return;\n\n      document.getElementById(\"story-modal-headline\").textContent = story.headline;\n      document.getElementById(\"story-modal-category\").textContent = story.category;\n      document.getElementById(\"story-modal-pages\").textContent = story.page_numbers;\n      \n      const sentEl = document.getElementById(\"story-modal-sentiment\");\n      sentEl.textContent = story.sentiment === \"BULLISH\" ? \"\ud83d\udfe2 BULLISH\" : story.sentiment === \"BEARISH\" ? \"\ud83d\udd34 BEARISH\" : \"\u26aa NEUTRAL\";\n      sentEl.className = `px-2 py-0.5 rounded text-[10.5px] font-mono font-bold border ${story.sentiment === \"BULLISH\" ? 'bg-emerald-50 text-emerald-800 border-emerald-200 dark:bg-emerald-950/60 dark:text-emerald-300' : story.sentiment === \"BEARISH\" ? 'bg-rose-50 text-rose-800 border-rose-200 dark:bg-rose-950/60 dark:text-rose-300' : 'bg-slate-100 text-slate-800 border-slate-200 dark:bg-slate-800 dark:text-slate-200'}`;\n\n      // Render KPIs in modal\n      const kpisContainer = document.getElementById(\"story-modal-kpis-container\");\n      if (kpisContainer) {\n        kpisContainer.innerHTML = buildKpiCardsHtml(story);\n      }\n\n      // Render brief details as crisp short chunks\n      const briefSentences = (story.brief_details || \"\").split(/(?<=[.?!])\\s+/).filter(Boolean);\n      const briefContainer = document.getElementById(\"story-modal-brief\");\n      briefContainer.innerHTML = briefSentences.map(sent => `\n        <div class=\"flex items-start gap-2 bg-white dark:bg-[#11172A] p-2 rounded-md border border-slate-200/80 dark:border-slate-800/80 text-[13px] text-slate-950 dark:text-slate-100 leading-snug font-medium\">\n          <span class=\"text-indigo-600 dark:text-indigo-400 font-black text-sm select-none\">\u25b8</span>\n          <span>${highlightNumbers(sent)}</span>\n        </div>\n      `).join('') || `<p class=\"text-xs text-slate-400\">No brief available.</p>`;\n\n      const bulletsContainer = document.getElementById(\"story-modal-bullets\");\n      bulletsContainer.innerHTML = (story.bullet_points || []).map(bp => `\n        <li class=\"flex items-start gap-2 text-[13px] text-slate-900 dark:text-slate-100 leading-snug bg-white dark:bg-[#11172A] p-2.5 rounded-lg border border-slate-200/80 dark:border-slate-800\">\n          <span class=\"text-indigo-600 dark:text-indigo-400 font-bold select-none\">\u203a</span>\n          <span>${highlightNumbers(bp)}</span>\n        </li>\n      `).join('') || `<li class=\"text-slate-400 text-xs\">No additional sub-bullets.</li>`;\n\n      document.getElementById(\"story-modal-catalyst\").innerHTML = highlightNumbers(story.sentimentReasoning || story.catalyst);\n\n      const tickersEl = document.getElementById(\"story-modal-tickers-container\");\n      tickersEl.innerHTML = (story.tickers || []).map(t => `<span class=\"px-2 py-0.5 text-[11px] font-mono font-bold rounded-md bg-indigo-50 text-indigo-900 border border-indigo-200 dark:bg-indigo-950/60 dark:text-indigo-200\">${t}</span>`).join('');\n\n      document.getElementById(\"story-modal\").classList.remove(\"hidden\");\n      document.getElementById(\"story-modal\").classList.add(\"flex\");\n    }\n\n    function closeStoryModal() {\n      const modal = document.getElementById(\"story-modal\");\n      modal.classList.add(\"hidden\");\n      modal.classList.remove(\"flex\");\n    }\n\n    // ================= IPO TABLE RENDERING =================\n    function filterIpoTable(tag) {\n      currentIpoFilter = tag;\n      document.querySelectorAll(\"[id^='ipo-stage-']\").forEach(btn => {\n        btn.className = \"px-2.5 py-0.5 rounded text-slate-300\";\n      });\n      const activeBtn = document.getElementById(`ipo-stage-${tag.toLowerCase()}`);\n      if (activeBtn) activeBtn.className = \"px-2.5 py-0.5 rounded bg-brand-600 text-white shadow-xs\";\n      renderIpoTable();\n    }\n\n    function renderIpoTable() {\n      const tbody = document.getElementById(\"ipo-table-body\");\n      tbody.innerHTML = \"\";\n      const rawQuery = document.getElementById(\"global-search\").value.trim().toLowerCase();\n      const queryTokens = rawQuery ? rawQuery.split(/\\s+/).filter(Boolean) : [];\n\n      const filtered = ipoList.filter(item => {\n        const matchTag = currentIpoFilter === \"ALL\" || item.filterTag === currentIpoFilter;\n        \n        const searchable = (item.company + \" \" + item.headline + \" \" + item.details + \" \" + item.size + \" \" + item.source + \" \" + item.exchange).toLowerCase();\n        const matchQuery = queryTokens.length === 0 || queryTokens.every(tok => searchable.includes(tok));\n        \n        return matchTag && matchQuery;\n      });\n\n      document.getElementById(\"ipo-table-visible-count\").textContent = filtered.length;\n\n      if (filtered.length === 0) {\n        tbody.innerHTML = `<tr><td colspan=\"8\" class=\"py-10 text-center text-slate-400 font-medium text-[13.5px]\">No IPO records found matching criteria.</td></tr>`;\n        return;\n      }\n\n      filtered.forEach((ipo, idx) => {\n        const tr = document.createElement(\"tr\");\n        tr.className = \"table-row-hover transition-colors border-b border-slate-100 dark:border-slate-800/80\";\n        const numStr = (idx + 1).toString().padStart(2, '0');\n        const demandColor = ipo.demand.includes(\"x\") ? \"text-emerald-700 dark:text-emerald-400 font-bold bg-emerald-50 dark:bg-emerald-950/40 px-2 py-0.5 rounded border border-emerald-200 dark:border-emerald-800\" : \"text-slate-600 dark:text-slate-400\";\n\n        tr.innerHTML = `\n          <td class=\"py-3 px-3.5 font-mono text-[12px] text-slate-400 font-semibold\">${numStr}</td>\n          <td class=\"py-3 px-3.5 font-bold text-slate-900 dark:text-white\">\n            <div class=\"flex items-start gap-2\">\n              <span class=\"w-6 h-6 rounded-md bg-brand-50 dark:bg-brand-950/60 text-brand-600 dark:text-brand-400 font-bold text-[10.5px] font-mono flex items-center justify-center shrink-0 border border-brand-200/50 mt-0.5\">\n                ${ipo.company.slice(0, 2).toUpperCase()}\n              </span>\n              <div>\n                <div class=\"flex items-center gap-1.5 flex-wrap\">\n                  <p class=\"text-[14px] leading-tight font-bold text-slate-900 dark:text-white\">${highlightSearchTokens(ipo.company, queryTokens)}</p>\n                  <span class=\"px-1.5 py-0.2 rounded text-[9.5px] font-mono font-bold bg-indigo-50 text-indigo-700 border border-indigo-200 dark:bg-indigo-950/60 dark:text-indigo-300\">${ipo.exchange}</span>\n                </div>\n                <p class=\"text-[11.5px] font-mono text-slate-400 font-normal truncate max-w-[240px] mt-0.5\">${highlightSearchTokens(ipo.headline, queryTokens)}</p>\n              </div>\n            </div>\n          </td>\n          <td class=\"py-3 px-3.5 font-mono font-bold text-slate-900 dark:text-slate-100 text-[13.5px] whitespace-nowrap\">${ipo.size}</td>\n          <td class=\"py-3 px-3.5 whitespace-nowrap\">\n            <span class=\"px-2 py-0.5 rounded text-[11.5px] font-mono font-bold border ${ipo.stageBadge}\">\n              ${ipo.stage}\n            </span>\n          </td>\n          <td class=\"py-3 px-3.5 font-mono text-[12px] whitespace-nowrap\"><span class=\"${demandColor}\">${ipo.demand}</span></td>\n          <td class=\"py-3 px-3.5 max-w-md\">\n            <div class=\"flex items-start gap-2\">\n              <p class=\"text-[13px] text-slate-700 dark:text-slate-300 leading-relaxed font-normal flex-1\">\n                ${highlightSearchTokens(highlightNumbers(ipo.details), queryTokens)}\n              </p>\n            </div>\n          </td>\n          <td class=\"py-3 px-3.5 font-mono text-[11.5px] text-slate-400 whitespace-nowrap\">${ipo.source}</td>\n          <td class=\"py-3 px-3.5 text-center whitespace-nowrap\">\n            <button onclick=\"openIpoModal(${idx})\" class=\"px-2.5 py-1 rounded-md border border-brand-200 dark:border-slate-700 bg-brand-50/80 dark:bg-[#182035] hover:bg-brand-600 hover:text-white text-brand-700 dark:text-brand-300 text-[11px] font-mono font-bold transition-all shadow-2xs flex items-center gap-1 mx-auto\" title=\"Click to view full IPO breakdown\">\n              <span>\u2139\ufe0f Details</span>\n            </button>\n          </td>\n        `;\n        tbody.appendChild(tr);\n      });\n    }\n\n    function openIpoModal(idx) {\n      const ipo = ipoList[idx];\n      if (!ipo) return;\n      document.getElementById(\"modal-ipo-company\").textContent = ipo.company;\n      document.getElementById(\"modal-ipo-exchange\").textContent = ipo.exchange;\n      document.getElementById(\"modal-ipo-stage\").textContent = ipo.stage;\n      document.getElementById(\"modal-ipo-size\").textContent = ipo.size;\n      document.getElementById(\"modal-ipo-demand\").textContent = ipo.demand;\n      document.getElementById(\"modal-ipo-headline\").textContent = ipo.headline;\n      document.getElementById(\"modal-ipo-details\").textContent = ipo.details;\n      document.getElementById(\"modal-ipo-source\").textContent = `Source Reference: ${ipo.source}`;\n      \n      const modal = document.getElementById(\"ipo-modal\");\n      modal.classList.remove(\"hidden\");\n      modal.classList.add(\"flex\");\n    }\n\n    function closeIpoModal() {\n      const modal = document.getElementById(\"ipo-modal\");\n      modal.classList.add(\"hidden\");\n      modal.classList.remove(\"flex\");\n    }\n\n    function highlightNumbers(text) {\n      if (!text) return \"\";\n      return text.replace(/(\\b\\d+(?:\\.\\d+)?%|\\b\u20b9\\s?[\\d,]+(?:\\.\\d+)?(?:\\s?(?:cr|crore|lakh|bn|billion|tn|trillion))?|\\b\\$[\\d,]+(?:\\.\\d+)?(?:\\s?(?:bn|billion|million|mn|tn))?|\\b[\\d,]+(?:\\.\\d+)?\\s?(?:crore|lakh|billion|million)\\b)/gi, '<span class=\"text-brand-600 dark:text-amber-400 font-bold font-mono\">$1</span>');\n    }\n\n    function highlightSearchTokens(text, tokens) {\n      if (!text || !tokens || tokens.length === 0) return text;\n      let result = text;\n      tokens.forEach(tok => {\n        if (!tok || tok.length < 2) return;\n        const regex = new RegExp(`(${escapeRegExp(tok)})`, 'gi');\n        result = result.replace(regex, '<mark>$1</mark>');\n      });\n      return result;\n    }\n\n    function escapeRegExp(string) {\n      return string.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\n    }\n\n    function escapeQuotes(str) {\n      return str.replace(/'/g, \"\\\\'\").replace(/\"/g, '&quot;');\n    }\n\n    function copyToClipboard(text) {\n      navigator.clipboard.writeText(text);\n      alert(\"Copied to clipboard!\");\n    }\n\n    document.addEventListener(\"keydown\", (e) => {\n      if (e.target.tagName === \"INPUT\" || e.target.tagName === \"SELECT\") return;\n      if (e.key === \"Escape\") closeIpoModal();\n      else if (e.key === \"j\" || e.key === \"ArrowDown\") {\n        e.preventDefault();\n        navigateStory(1);\n      } else if (e.key === \"k\" || e.key === \"ArrowUp\") {\n        e.preventDefault();\n        navigateStory(-1);\n      } else if (e.key === \"ArrowLeft\" || e.key === \"[\") {\n        e.preventDefault();\n        navigateDate(1);\n      } else if (e.key === \"ArrowRight\" || e.key === \"]\") {\n        e.preventDefault();\n        navigateDate(-1);\n      } else if (e.key === \"1\") switchView('feed');\n      else if (e.key === \"2\") switchView('anchor');\n      else if (e.key === \"3\") switchView('ipo');\n      else if (e.key === \"/\") { e.preventDefault(); document.getElementById(\"global-search\").focus(); }\n    });\n\n    initTheme();\n    fetchDates();\n    loadData();\n  </script>\n</body>\n</html>\n";
export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // API Routes
    if (url.pathname === '/api/report') {
      const dateParam = url.searchParams.get('date');
      const targetFile = dateParam ? `news_report_unified_${dateParam}.json` : 'news_report_unified_latest.json';
      const r2Url = `https://pub-c81167dd545d49d0a2cd964a8bd6a1cd.r2.dev/reports/${targetFile}?t=${Date.now()}`;
      try {
        const resp = await fetch(r2Url, {
          headers: { 'User-Agent': 'FinPress-Cloudflare-Worker' },
          cf: { cacheTtl: 0, cacheEverything: false }
        });
        return new Response(resp.body, {
          status: resp.status,
          headers: {
            'Content-Type': 'application/json; charset=utf-8',
            'Access-Control-Allow-Origin': '*',
            'Cache-Control': 'no-cache, no-store, must-revalidate',
            'Pragma': 'no-cache',
            'Expires': '0'
          }
        });
      } catch (e) {
        return new Response(JSON.stringify({ error: 'Failed to fetch report' }), { status: 500 });
      }
    }

    if (url.pathname === '/api/dates') {
      const dates = ['2026-09-28', '2026-09-27'];
      return new Response(JSON.stringify(dates), {
        headers: {
          'Content-Type': 'application/json; charset=utf-8',
          'Access-Control-Allow-Origin': '*',
          'Cache-Control': 'no-cache, no-store, must-revalidate'
        }
      });
    }

    // Default: Serve Trader Terminal UI
    return new Response(HTML, {
      headers: {
        'Content-Type': 'text/html; charset=utf-8',
        'Cache-Control': 'no-cache, no-store, must-revalidate'
      }
    });
  }
};
